const top_ksante = {
  champion: '크산테',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '1~2레벨에는 (Q)\'엔토포 타격\'으로 가볍게 견제하며 가렌의 (P)\'인내심\' 회복을 방해하세요. 가렌이 (Q)\'결정타\'로 빠르게 달려와 침묵을 걸려 하면 거리를 벌려 최대한 피해를 줄여야 해요. (Q)\'결정타\'는 둔화 효과를 모두 제거하니 (Q)\'엔토포 타격\'의 둔화로 가렌의 접근을 늦출 생각은 하지 마세요.', lv3: '가렌이 (E)\'심판\'을 돌리며 접근하면 (W)\'길을 여는 자\'를 충전해 받는 피해를 줄이고 가렌을 기절시키며 밀어내세요. (E)\'발놀림\'의 보호막을 활용해 (Q)\'결정타\'의 피해를 흡수하고 빠르게 빠져나오는 것이 좋아요. (Q)\'엔토포 타격\'을 두 번 맞혀 충격파로 기절시키면 가렌이 (W)\'용기\' 보호막을 켜기 전의 빈틈을 노릴 수 있어요.', lv6: '체력이 낮을 때 (R)\'데마시아의 정의\'를 맞으면 바로 처치될 수 있으니 항상 체력 관리에 유의하세요. 가렌이 (W)\'용기\' 보호막을 쓴 뒤에 (R)\'총공세\'로 벽 너머로 밀어내어 피해를 입히고 빠르게 몰아붙이는 것이 좋아요. 라인을 적당히 밀어 두고 정글러가 오면 (Q)\'엔토포 타격\'의 충격파로 가렌을 기절시켜 호응하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 가렌의 기본 공격 피해를 줄여주고, 갈라진 하늘은 체력을 보충하며 공격력을 높여 교환을 도와줘요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 가렌의 (P)\'인내심\' 회복을 억제해야 킬각을 잡기 쉬워요.' },
    '갱플랭크': { lv1: '웨이브 시작부터 갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 골드를 챙기며 견제하니 미니언 뒤에 있어도 맞을 수 있음을 인지하세요. (Q)\'엔토포 타격\'의 둔화를 활용해 짧게 딜교환을 하고 빠지는 것이 좋아요. (P)\'불의 심판\'이 붙은 근접 공격을 맞지 않게 거리를 조절하세요.', lv3: '갱플랭크가 깔아둔 (E)\'화약통\' 근처에서 싸우면 폭발 피해와 둔화에 노출되니 주의하세요. (W)\'괴혈병 치료\'로 군중 제어를 풀고 체력을 회복할 수 있으니, (W)\'길을 여는 자\'로 진입하기 전에 상대의 회복 스킬이 빠졌는지 확인하는 것이 중요해요.', lv6: '(R)\'총공세\'를 사용하면 방어력이 낮아지지만 강력한 돌진이 가능하니, 갱플랭크의 (W)\'괴혈병 치료\'가 없을 때 몰아붙여야 해요. 갱플랭크가 (R)\'포탄 세례\'를 사용해 지역을 장악하면 추격이 어려워지니, 포격이 끝나거나 범위 밖에서 (E)\'발놀림\'으로 거리를 좁히며 진입하세요. 갱플랭크가 (R)\'포탄 세례\'를 다른 라인에 쓴 직후에는 라인을 밀어 두고 정글러와 함께 압박하세요.', item: '판금 장화를 먼저 올려 갱플랭크의 기본 공격 피해를 줄여주세요. 첫 코어 아이템으로는 전투 지속력을 높여주는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 갱플랭크가 (W)\'괴혈병 치료\'로 버티지 못하게 점화로 회복량을 줄이며 킬각을 잡으세요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고 (P)\'서비스 시간\'으로 체력을 회복해서 초반에 괴롭혀요. 술통이 굴러오는 궤적을 피해 거리 조절을 하고, 그라가스가 무리하게 들어올 때 (Q)\'엔토포 타격\'으로 둔화를 걸어 대응하세요. 억지로 들어가기보다 경험치를 챙기며 체력을 보존하세요.', lv3: '그라가스가 (E)\'몸통 박치기\'로 진입해 기절시키려 할 때 (W)\'길을 여는 자\'의 피해 감소와 저지 불가 상태로 이를 받아내세요. (W)\'취중 분노\'를 사용해 피해를 줄이는 타이밍에는 스킬을 아끼고, 효과가 끝난 뒤 (E)\'발놀림\'으로 진입해 빠르게 딜교환을 하세요. (Q)\'엔토포 타격\'을 두 번 맞혀 충격파로 적을 기절시키면 딜교환에서 앞설 수 있어요.', lv6: '그라가스가 (R)\'술통 폭발\'로 밀어내어 거리 조절을 하려 하니, 벽 근처에서 (R)\'총공세\'를 사용해 적을 벽 너머로 날려 보내며 킬각을 잡으세요. 이후 강화된 (Q)\'엔토포 타격\'을 빠르게 적중시켜 적을 계속 압박하세요. 정글러가 개입할 때 그라가스의 밀쳐내기에 당해 아군 진영과 떨어지지 않도록 주의하세요.', item: '갈라진 하늘을 가서 체력과 공격력을 챙기고 전투 중 체력을 회복하며 버티세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 추천해요. 강인함은 (Q)\'술통 굴리기\' 둔화 지속시간을 줄여줘요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (R)\'총공세\'의 각을 만들고 순간이동으로 빠르게 라인에 복귀하세요.' },
    '그웬': { lv1: '1~2레벨에는 그웬의 (P)\'가위 난도질\'이 체력 비례 마법 피해를 넣고 챔피언을 때릴 때 체력을 회복하니 길게 교환하지 말고 짧게 끊으세요. (Q)\'엔토포 타격\'으로 미니언 사이에서 그웬을 견제하며 거리를 조절하세요. (Q)\'싹둑싹둑!\'은 평타로 가위질이 중첩될수록 강해지니 평타 교환이 길어지지 않게 하세요.', lv3: '크산테의 (Q)\'엔토포 타격\'과 (W)\'길을 여는 자\'는 대상 지정 스킬이 아니라서 그웬이 (W)\'신성한 안개\'를 써도 그대로 맞아요. 다만 안개 안에서는 그웬의 방어력과 마법 저항력이 늘어나니 안개가 걷힌 뒤에 교환하세요. 그웬이 (E)\'돌격가위\'로 진입할 때 (W)\'길을 여는 자\'로 흐름을 끊고 기절을 노리세요.', lv6: '(R)\'총공세\' 상태에서는 방어력과 마법 저항력이 낮아지므로 그웬의 (R)\'바느질\'을 다 맞지 않도록 주의하며 싸우세요. (R)\'바느질\'은 재사용할수록 바늘이 늘어나니 첫 바늘을 피하는 것이 중요해요. 라인을 빠르게 밀어넣고 정글러의 도움을 받아 그웬을 상대하세요.', item: '첫 코어로 갈라진 하늘을 선택하여 전투 지속력을 높이세요. 신발은 그웬의 마법 피해를 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 그웬은 패시브와 스킬로 체력을 회복하니 점화로 회복을 줄여야 해요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 원거리에서 둔화를 걸며 견제하니 부메랑 궤적을 잘 살펴야 해요. 1~2레벨에는 무리하게 다가가기보다 미니언을 챙기며 거리를 조절하고, 나르의 (W)\'슝슝\' 추가 피해가 쌓이지 않게 주의하세요. (Q)\'엔토포 타격\'을 맞혀 중첩을 쌓으며 다음 공격 기회를 노려보세요.', lv3: '나르가 (E)\'폴짝\'으로 거리를 벌릴 때 (E)\'발놀림\'으로 빠르게 따라붙어 딜교환을 시도하세요. (Q)\'부메랑 던지기\'를 피하면서 (Q)\'엔토포 타격\'을 맞춰서 충격파로 적을 끌어당기는 것이 중요해요. (W)\'길을 여는 자\'를 사용해 나르의 공격을 버티며 싸우는 것이 좋아요.', lv6: '메가 나르의 (R)\'나르!\'는 벽에 부딪히면 기절을 일으키니 벽 근처에서는 싸움을 피해야 해요. (R)\'총공세\'를 사용하여 강력한 피해를 입히고, 나르의 (W)\'쿵쾅\' 기절이 들어오기 전에 (W)\'길을 여는 자\'로 대응하거나 거리를 조절하세요. 정글러가 근처에 있다면 메가 나르를 압박해 킬을 노려보세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 기본 공격으로 받는 피해량을 줄여주고, 갈라진 하늘은 체력을 높여줘요.', spell: '점멸과 점화. 점화로 나르의 체력을 깎으며 마무리 피해를 입히세요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'으로 스택을 쌓으며 성장하니 초반에 적극적으로 압박해야 해요. (Q)\'엔토포 타격\'을 적중시켜 둔화시킨 뒤 평타를 섞어 나서스가 미니언을 편하게 먹지 못하도록 방해하세요. 나서스의 초반 몸싸움이 약한 구간을 활용해 라인을 밀어 넣는 것이 좋아요.', lv3: '나서스의 (W)\'쇠약\'이 빠진 것을 확인하고 딜교환을 시작하세요. (W)\'길을 여는 자\'로 돌진하며 상대의 공격을 받아내고 (Q)\'엔토포 타격\'의 충격파를 맞히는 구도를 만드세요. (E)\'영혼의 불길\'이 깔린 지역은 방어력을 낮추니 그 위에서 싸우지 않도록 조심하세요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력과 공격 범위가 늘어나니 무리하게 싸우지 마세요. (R)\'총공세\' 상태에서는 (E)\'발놀림\'의 재사용 대기시간이 줄어드니 (Q)\'흡수의 일격\'이 준비된 나서스와 거리를 조절하며 싸워야 해요. 정글러의 개입을 유도해 나서스가 미니언 스택을 쌓는 것을 방해하며 라인을 관리하세요.', item: '체력과 공격력을 보강하기 위해 갈라진 하늘을 첫 코어로 가세요. 신발은 나서스의 기본 공격 피해를 줄이기 위해 판금 장화를 가세요.', spell: '점멸과 점화를 추천해요. 점화로 나서스의 (P)\'영혼의 포식자\' 체력 회복 효과를 줄이며 압박하세요.' },
    '녹턴': { lv1: '1~2레벨 구간에서는 (Q)\'엔토포 타격\' 중첩을 쌓으며 차분하게 파밍에 집중하세요. (Q)\'황혼의 인도자\'에 맞으면 궤적이 남아 녹턴이 이동 속도를 얻고 빠르게 따라붙으니 칼날이 날아오는 방향을 보고 비켜서세요. 무리하게 들어가기보다는 미니언을 타고 안전하게 거리를 유지하며 성장하세요.', lv3: '3레벨 이후에는 (W)\'길을 여는 자\'를 사용하여 상대의 공격을 버텨내며 딜교환을 준비하세요. 상대의 (W)\'어둠의 장막\'이 빠진 것을 확인한 뒤에 (Q)\'엔토포 타격\'으로 기절을 노리는 것이 좋아요. (E)\'발놀림\'으로 거리를 조절하며 (E)\'말할 수 없는 공포\'의 연결이 끊기도록 사거리 밖으로 벗어나세요.', lv6: '상대가 (R)\'피해망상\'을 사용하면 시야가 줄어드니 무리하게 라인에 서 있지 말고 체력을 관리하세요. (R)\'총공세\' 상태에서는 공격 속도와 방어구 관통력이 늘어나니 (E)\'말할 수 없는 공포\'가 끝난 직후에 교환을 시도하면 좋아요. 방어력이 낮아지니 정글러의 개입을 경계하며 라인 상황을 항상 확인하세요.', item: '판금 장화와 얼어붙은 심장을 추천해요. 상대의 기본 공격 피해를 줄이고 방어력을 높여 지속 싸움에서 버티기 위해서예요.', spell: '점멸과 탈진. 상대가 돌진해 들어올 때 탈진을 사용하면 입히는 피해량을 감소시킬 수 있어요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\' 중첩이 쌓이면 매우 강해지니 1~2레벨에는 길게 싸우지 마세요. (Q)\'엔토포 타격\'으로 둔화를 걸며 짧게 딜교환하고 빠르게 빠지는 것이 중요해요. (Q)\'학살\'의 도끼날 끝에 맞지 않도록 주의하며 거리를 조절하세요.', lv3: '(E)\'포획\'에 끌려오면 (P)\'과다출혈\' 중첩이 빠르게 쌓이니 거리 조절에 유의하세요. (E)\'포획\'이 빠진 것을 확인한 뒤에 (W)\'길을 여는 자\'로 진입해 적을 기절시키고 밀어내세요. (E)\'발놀림\'으로 보호막을 얻으며 짧게 치고 빠지는 구도를 만드세요.', lv6: '(R)\'녹서스의 단두대\'는 출혈 중첩이 높을 때 치명적이니 중첩이 쌓이기 전에 (R)\'총공세\'로 밀어내어 흐름을 끊으세요. 벽 쪽으로 상대를 밀어 넣어 추가 피해를 입히고 빠르게 딜교환을 마무리하세요. 상대의 (Q)\'학살\' 회복량을 고려해 체력이 낮을 때는 무리하게 붙지 마세요.', item: '판금 장화는 기본 공격 피해를 줄여 주어 다리우스의 평타 견제를 버티게 해 줘요. 얼어붙은 건틀릿을 첫 코어로 선택해 방어력과 체력을 높여 생존력을 확보하세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 (Q)\'학살\'을 통한 다리우스의 체력 회복을 억제하며 킬각을 잡으세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 직선으로 쏘아 견제하는데 첫 번째 맞는 적에게 피해를 입히니 미니언 뒤에 숨어 피해를 최소화하세요. 1~2레벨에는 (Q)\'엔토포 타격\'의 둔화로 거리를 좁히려 해도 라이즈의 사거리가 더 길어 쉽게 붙기 어려워요. 무리하게 들어가지 말고 경험치 위주로 받으며 체력을 보존하세요.', lv3: '(E)\'주문 전이\' 표식이 붙은 채로 (W)\'룬 감옥\'을 맞으면 둔화 대신 속박되니 표식이 붙은 상태로 라이즈 사거리 안에 오래 머물지 마세요. 속박은 이동만 막으니 걸려도 (Q)\'엔토포 타격\'은 쓸 수 있어요. 라이즈가 (W)\'룬 감옥\'을 낭비했다면 (E)\'발놀림\'으로 빠르게 진입해 (Q)\'엔토포 타격\'을 두 번 맞혀 기절시키세요.', lv6: '라이즈가 (W)\'룬 감옥\'을 쓰기 전에 (R)\'총공세\'로 벽 쪽으로 밀어내어 추가 피해를 입히면 빠르게 체력을 깎을 수 있어요. (R)\'공간 왜곡\'은 아군과 함께 순간이동하는 스킬이니 라이즈가 차원문을 열면 정글러의 개입을 주의하고 라인을 조절하세요. 총공세 상태에서는 (E)\'발놀림\' 속도가 빨라지니 라이즈의 무빙을 따라가며 압박하세요.', item: '헤르메스의 발걸음과 케이닉 루컨을 추천해요. 헤르메스의 발걸음은 마법 저항력과 강인함으로 (W)\'룬 감옥\' 속박과 둔화 지속시간을 줄여줘요. 케이닉 루컨은 높은 마법 저항력과 체력을 제공해요.', spell: '점멸과 순간이동을 추천해요. 라이즈의 강력한 라인 푸시력에 대응해 빠르게 복귀하고 정글러와 함께 덮치는 전략이 필요해요.' },
    '럼블': { lv1: '럼블이 (Q)\'화염방사기\'를 사용해 근접 거리에서 지속적인 마법 피해를 입히니 미니언과 거리를 두며 파밍에 집중하세요. (Q)\'엔토포 타격\'의 중첩을 쌓으려다 (E)\'전기 작살\'에 맞으면 마법 저항력이 감소하니 주의하며 적절한 사거리를 유지해야 해요.', lv3: '럼블이 (W)\'고철 방패\'로 피해를 흡수할 때는 (E)\'발놀림\'으로 빠르게 접근하거나 거리를 벌리세요. 럼블의 (E)\'전기 작살\'을 피한 뒤 (Q)\'엔토포 타격\'을 적중시켜 둔화를 걸고 딜교환을 시작하세요. 럼블의 열기가 높아져 과열 상태가 되면 스킬을 사용하지 못하는 빈틈이 생겨요.', lv6: '럼블이 (R)\'이퀄라이저 미사일\'을 사용하면 불타는 궤적 안에서 싸우지 말고 즉시 밖으로 벗어나세요. (R)\'총공세\'로 변신한 뒤 럼블을 벽 너머로 밀쳐내고 (Q)\'엔토포 타격\'의 충격파로 기절시키면 킬각을 잡을 수 있어요. 럼블의 궁극기는 범위가 넓으니 라인을 밀었을 때는 정글러의 위치를 꼭 확인하세요.', item: '첫 코어로 갈라진 하늘을 올려 전투 지속력을 높이세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음을 선택해 럼블의 마법 피해와 둔화를 견디세요.', spell: '점멸과 점화를 추천해요. 럼블의 (W)\'고철 방패\'가 있어도 킬을 확실하게 마무리하기 위해서예요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 피해를 입히고 체력을 회복하며 1~2레벨 초반 교환에서 강한 모습을 보여요. (Q)\'엔토포 타격\'으로 적을 둔화시키며 거리를 조절하고 최대한 미니언을 먼저 챙기세요. 레넥톤이 분노를 쌓아 강화된 (Q)\'양떼 도륙\'을 쓰지 못하도록 거리를 유지하는 것이 중요해요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입한 뒤 (W)\'무자비한 포식자\'로 기절을 시도하니 주의해야 해요. (W)\'길을 여는 자\'를 사용하여 레넥톤의 돌진에 대응하며 받는 피해를 줄이세요. 레넥톤의 분노가 높을 때는 보호막을 부수는 (W)\'무자비한 포식자\'가 매우 강력하니 적극적인 교환을 피해요.', lv6: '레넥톤이 (R)\'강신\'을 사용하면 체력이 늘어나고 분노가 빠르게 차오르니 정면 승부는 조심하세요. (R)\'총공세\'를 사용해 적을 벽 너머로 밀어내고 변형된 스킬로 압박하며 변수를 만드세요. 라인을 밀어 넣고 정글러의 개입에 대비해 (W)\'길을 여는 자\'의 저지 불가 상태를 활용하며 자리를 잡으세요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 레넥톤의 물리 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 탈진을 추천해요. 탈진으로 레넥톤의 순간적인 돌진 피해를 줄여 교환을 이끌 수 있어요.' },
    '렝가': { lv1: '수풀에 들어가지 말고 거리 조절을 하며 (Q)\'엔토포 타격\'으로 둔화를 거세요. 렝가가 (Q)\'포악함\'으로 진입할 때 너무 깊게 들어가지 않도록 주의하세요. 첫 웨이브는 최대한 사리며 경험치만 챙겨요.', lv3: '렝가가 (E)\'올가미 투척\'을 던질 때 (E)\'발놀림\'으로 피하거나 (W)\'길을 여는 자\'의 저지 불가 상태로 무시하세요. (Q)\'엔토포 타격\'을 두 번 맞혀 기절시킨 뒤 짧게 딜교환하고 빠지세요. (W)\'전투의 포효\'로 체력을 회복하기 전에 빠르게 전투를 마무리하세요.', lv6: '(R)\'사냥의 전율\'을 사용한 기습 진입 시 (R)\'총공세\'로 적을 밀어내어 벽에 부딪히게 하세요. 라인을 밀어 렝가가 수풀을 활용하지 못하게 하고 정글러의 개입을 유도하세요. (R)\'총공세\' 상태에서는 방어력이 낮아지니 진입 타이밍을 신중하게 잡으세요.', item: '판금 장화와 가시 갑옷을 추천해요. 판금 장화는 렝가의 기본 공격 피해를 줄여주고 가시 갑옷은 (W)\'전투의 포효\'의 회복력을 낮춰줘요.', spell: '점멸과 점화예요. 점멸로 변수를 만들고 점화로 렝가의 회복 수단을 억제하며 마무리 피해를 입히세요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'와 (P)\'룬 검\'을 사용해 초반에 빠르게 진입하며 강한 피해를 입혀요. (Q)\'엔토포 타격\'으로 둔화를 걸어 거리를 벌리며 리븐이 함부로 들어오지 못하게 압박하세요. 리븐이 (Q)\'부러진 날개\' 세 번째 타격으로 밀쳐내기 전까지는 짧게 딜교환을 하고 빠지는 게 좋아요.', lv3: '리븐이 (W)\'기 폭발\'로 기절시키려 할 때 (W)\'길을 여는 자\'의 저지 불가 상태로 이를 무시하며 진입하세요. 리븐이 (E)\'용맹\'으로 보호막을 두른 동안은 딜을 아끼고, (E)\'발놀림\' 보호막으로 리븐의 연계를 받아낸 뒤 (Q)\'엔토포 타격\'을 두 번 맞춰 기절시키세요. 리븐의 콤보가 모두 빠진 뒤에 평타와 (Q)\'엔토포 타격\'으로 딜교환을 주도하세요.', lv6: '(R)\'총공세\'를 사용해 리븐을 벽 쪽으로 밀어내면 추가 피해를 입히고 강하게 압박할 수 있어요. 리븐이 (R)\'추방자의 검\'을 켜면 공격 사거리가 늘어나니 체력이 낮을 때는 거리 조절에 주의하세요. 정글러가 올 때 (R)\'총공세\'로 리븐을 벽 너머로 보내 아군과 함께 빠르게 정리하세요.', item: '판금 장화를 신어 리븐의 (P)\'룬 검\'이 섞인 기본 공격 피해를 줄이세요. 얼어붙은 건틀릿을 첫 코어로 선택해 높은 방어력을 얻고 스킬 사용 후 둔화 효과로 리븐의 추격을 늦추세요. 이렇게 하면 리븐의 진입을 더 효과적으로 막아낼 수 있어요.', spell: '점멸과 순간이동을 추천해요. 리븐의 기동성이 높으므로 점멸로 변수를 만들고 순간이동으로 빠른 합류와 라인 복귀를 하세요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'이 미니언을 관통하며 둔화를 걸기 때문에 미니언 바로 뒤에 서지 말고 옆으로 비켜서세요. 1~2레벨에는 (Q)\'엔토포 타격\'을 적중시켜 중첩을 쌓으며 접근할 타이밍을 노리는 것이 좋아요. 무리하게 진입하기보다는 적절한 거리를 유지하며 체력을 관리하세요.', lv3: '리산드라가 (W)\'서릿발\'로 발을 묶으려 할 때 (W)\'길을 여는 자\'의 저지 불가 상태를 이용해 돌진하며 받아치세요. 리산드라가 (E)\'얼음갈퀴 길\'로 이동하면 (E)\'발놀림\'을 사용하여 빠르게 거리를 좁히세요. (Q)\'엔토포 타격\' 중첩을 쌓아 충격파를 맞히면 안정적인 딜교환을 할 수 있어요.', lv6: '리산드라가 자신에게 (R)\'얼음 무덤\'을 사용해 무적 상태가 되면 잠시 공격을 멈추고 기다리세요. 리산드라가 나에게 (R)\'얼음 무덤\'을 써서 기절시킨다면 정글러의 개입을 경계하며 조심해야 해요. (R)\'총공세\'를 켰을 때는 방어력과 마법 저항력이 낮아지므로 리산드라의 마법 피해에 주의하며 싸우세요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 (W)\'서릿발\'과 (R)\'얼음 무덤\'의 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 리산드라가 자신에게 (R)\'얼음 무덤\'을 써서 체력을 회복할 때 점화로 대응하거나 체력이 낮은 적을 마무리하기 좋아요.' },
    '마스터이': { lv1: '마스터 이의 (P)\'2연속 공격\'은 초반 평타 교환이 강하니 (Q)\'엔토포 타격\'으로 거리를 유지하며 견제하세요. 1~2레벨에는 무리하게 붙기보다 (Q)\'엔토포 타격\'의 둔화를 활용해 마스터 이의 접근을 늦추세요.', lv3: '마스터 이가 (Q)\'일격 필살\'을 사용해 대상으로 지정할 수 없게 되면 맞서지 말고 기다리세요. (Q)\'일격 필살\'이 빠진 직후 (W)\'길을 여는 자\'로 마스터 이를 밀어내거나 (Q)\'엔토포 타격\'을 사용하여 딜교환을 시도해요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 켜면 둔화 면역이 되므로 (Q)\'엔토포 타격\'의 둔화 효과에 의존하지 마세요. (R)\'총공세\' 상태에서 마스터 이의 체력이 낮을 때 킬각을 보고, 마스터 이가 성장을 멈추도록 라인 관리를 하며 정글러의 개입을 유도하세요.', item: '갈라진 하늘을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'명상\'으로 체력을 회복하는 마스터 이의 생존력을 억제해야 해요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 거리를 벌리며 둔화를 걸고 (P)\'마법 흡수\'로 회복을 챙기려 해요. 1~2레벨에는 (Q)\'엔토포 타격\'을 맞춰 중첩을 쌓으며 짧게 딜교하세요. 마오카이가 (E)\'묘목 던지기\'를 뿌린 수풀 근처에서는 거리를 두는 것이 좋아요.', lv3: '(W)\'뒤틀린 전진\'은 대상에게 돌진해 속박하니 걸어서 피하려 하기보다 쓰게 만든 뒤 빈틈을 노리세요. 속박은 이동만 막으니 걸려도 (Q)\'엔토포 타격\'은 쓸 수 있어요. 마오카이가 (W)\'뒤틀린 전진\'을 사용한 뒤에는 (Q)\'엔토포 타격\' 중첩으로 기절과 끌어당기기를 노리고 (E)\'묘목 던지기\'가 깔린 수풀 근처는 조심하세요.', lv6: '마오카이가 (R)\'대자연의 마수\'를 쓰면 벽이 오는 방향을 보고 옆으로 비켜서 속박을 피하세요. 마오카이의 핵심 CC기가 빠진 시점에 (R)\'총공세\'를 켜고 진입하여 강하게 몰아붙이세요. (R)\'총공세\' 상태에서는 방어력이 감소하니 무리하게 교전하지 않도록 주의해요.', item: '마법 피해가 주력인 마오카이를 상대하기 위해 헤르메스의 발걸음을 신발로 선택하세요. 첫 코어 아이템으로는 전투 지속력을 높여주는 갈라진 하늘을 추천해요.', spell: '점멸과 점화. 마오카이의 (P)\'마법 흡수\' 회복을 억제하며 킬각을 잡기 좋아요.' },
    '말자하': { lv1: '말자하의 (Q)\'공허의 부름\'은 두 문 사이로 파동이 지나가는 스킬이라 미니언으로 막을 수 있다고 가정하지 말고 문이 열리는 위치를 보고 움직이세요. 먼저 평타나 (Q)\'엔토포 타격\'으로 적을 공격하여 (P)\'공허 태세\'의 피해 감소 효과를 벗겨내야 해요. 1~2레벨 구간에서는 말자하의 사거리가 길어 압박이 심하니 거리를 조절하며 버티세요.', lv3: '말자하가 (E)\'재앙의 환상\'을 걸고 (W)\'공허의 무리\'를 소환하면 공허충 때문에 딜교환이 힘들어져요. (W)\'길을 여는 자\'로 진입하기 전에 말자하의 (Q)\'공허의 부름\'을 먼저 빼는 것이 좋아요. (Q)\'엔토포 타격\'의 충격파를 맞히면 말자하를 멈출 수 있어요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없고 맞으면 스킬과 점멸도 쓸 수 없으니 사거리 안에 오래 머물지 마세요. 말자하의 (P)\'공허 태세\'가 켜져 있으면 군중 제어에 면역이니 먼저 피해를 입혀 벗겨낸 뒤 (R)\'총공세\'로 진입하세요. 말자하가 궁극기를 쓰면 무리하게 싸우지 말고 뒤로 물러나 정글러를 부르세요.', item: '헤르메스의 발걸음을 구매해 마법 저항력과 강인함을 챙기세요. 첫 코어 아이템으로는 체력과 공격력을 모두 제공하는 갈라진 하늘이 적절해요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니 점화로 말자하의 체력을 깎아 킬각을 만드세요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 피해를 입히며 이동 속도를 훔치는데 이는 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (P)\'화강암 방패\'는 공격받지 않으면 다시 생기니 (Q)\'엔토포 타격\'으로 먼저 방패를 깎고 다시 생기기 전에 교환을 이어가세요. (Q)\'엔토포 타격\'의 두 번 중첩 충격파를 활용해 미니언과 함께 압박하는 것이 좋아요.', lv3: '말파이트의 (E)\'지면 강타\'에 맞으면 내 공격 속도가 줄어드니 평타 교환보다 스킬 위주로 싸우세요. (W)\'천둥소리\'의 강화 평타를 맞지 않도록 주의하며 (W)\'길을 여는 자\'로 말파이트의 공격을 버티면서 (E)\'발놀림\'으로 진입하세요. (Q)\'엔토포 타격\'의 둔화 효과를 이용해 원하는 위치에서 싸움을 설계하는 것이 중요해요.', lv6: '말파이트가 (R)\'멈출 수 없는 힘\'으로 공중에 띄우면 스킬을 쓸 수 없으니 정글러가 근처에 있다면 조심하세요. (R)\'총공세\'를 사용하면 피해량과 체력 회복량이 늘어나니 궁극기가 빠진 뒤에 몰아붙이세요. (E)\'발놀림\'과 (R)\'총공세\'를 활용해 적극적으로 압박하며 라인을 주도하세요.', item: '말파이트의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 먼저 갖추세요. 첫 코어 아이템으로는 공격력과 체력을 제공하는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. (R)\'멈출 수 없는 힘\'이 빠진 뒤 점화로 (P)\'화강암 방패\'가 다시 생기기 전에 마무리 피해를 넣기 좋아요.' },
    '모데카이저': { lv1: '모데카이저는 (Q)\'말살\'을 한 명에게만 맞히면 피해가 크니 미니언과 함께 맞도록 위치를 잡으세요. (Q)\'엔토포 타격\'으로 둔화를 걸며 짧게 교환하고 (P)\'암흑 탄생\' 오라가 켜지기 전에 빠르게 빠지세요. 첫 웨이브는 최대한 거리 조절을 하며 체력 손실을 줄이는 것이 중요해요.', lv3: '(E)\'죽음의 손아귀\'에 끌려갔을 때는 (W)\'길을 여는 자\'를 충전해 받는 피해를 줄이고 모데카이저를 밀어내며 기절시키세요. (W)\'불멸\' 보호막이 활성화된 상태에서는 긴 싸움을 피하고 (E)\'발놀림\'으로 빠르게 거리를 벌려 보호막이 사라지길 기다려요. (Q)\'엔토포 타격\'을 두 번 적중시켜 상대를 기절시킨 뒤 짧게 공격하세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 수은 장식띠로도 풀 수 없고 순간이동으로도 빠져나갈 수 없으니 그 안에서 최대한 버티세요. (R)\'총공세\'로 모데카이저를 밀어내고 돌진해 붙을 수 있으니 (E)\'죽음의 손아귀\'가 빠진 타이밍에 진입해 짧게 몰아붙이세요. 정글러가 개입하기 좋게 라인을 당겨 두세요.', item: '맬모셔스의 아귀를 첫 코어로 가서 마법 저항력을 높이고 생명선 보호막으로 모데카이저의 마법 피해를 막으세요. 신발은 마법 저항력과 강인함이 있는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 순간이동을 추천해요. 라인 관리와 복귀가 중요하고 (R)\'총공세\'와 점멸을 연계해 적을 벽 너머로 날려버리기 좋기 때문이에요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 현재 체력 비례 피해를 주며 둔화를 걸어요. 이 투사체는 처음 맞는 대상에게 적중하니 미니언 뒤에 서서 막으며 거리를 조절하세요. (Q)\'엔토포 타격\'을 활용해 짧게 견제하며 문도가 (Q)\'오염된 뼈톱\'으로 체력을 회복하지 못하게 하세요.', lv3: '문도 박사가 (W)\'심장 전기 충격\'을 켜고 다가오면 저장된 피해가 폭발할 수 있으니 주의하세요. (E)\'발놀림\'으로 진입할 때 문도의 (Q)\'오염된 뼈톱\' 사거리를 확인하고 (Q)\'엔토포 타격\' 중첩을 쌓아 기절을 노려보세요. (W)\'심장 전기 충격\'을 재사용하기 전에 거리를 벌리거나 스킬을 활용해 딜교환을 마무리하세요.', lv6: '(R)\'최대 투여량\'을 사용한 문도 박사는 체력을 크게 회복하니 궁극기 사용 직후에는 무리하게 추격하지 마세요. (R)\'총공세\'로 문도 박사를 벽 쪽으로 밀어낸 뒤 강화된 스킬로 압박을 이어가세요. 문도의 회복량이 매우 높으니 정글러와 함께 압박하거나 라인을 빠르게 밀어 다른 곳을 견제하세요.', item: '문도 박사의 체력 회복을 억제하기 위해 가시 갑옷을 첫 코어로 선택하세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 문도 박사의 (R)\'최대 투여량\' 회복 효과를 줄여야 킬각을 잡을 수 있어요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'의 긴 사거리로 일방적인 견제를 시도해요. (Q)\'엔토포 타격\'을 맞히기 위해 거리를 조절하며 미니언 사이에서 무리하게 나가지 마세요. (E)\'발놀림\'의 보호막을 활용해 바루스의 초반 공격을 받아내며 성장하세요.', lv3: '바루스가 (E)\'퍼붓는 화살\'로 지면을 오염시키면 이동 속도가 느려지니 주의하세요. 바루스가 (W)\'역병 화살\'을 쓴 뒤 (Q)\'꿰뚫는 화살\'로 역병을 터뜨리려 할 때 (W)\'길을 여는 자\'로 돌진해 거리를 좁히세요. (Q)\'엔토포 타격\' 중첩을 이용해 바루스를 끌어당기면 딜교환을 더 효과적으로 할 수 있어요.', lv6: '바루스의 (R)\'부패의 사슬\'은 처음 맞은 대상을 속박하니 진입하기 전에 스킬을 피하는 것이 중요해요. (R)\'총공세\'를 사용하면 방어력이 감소하므로 바루스의 강력한 피해에 주의하며 전투를 이어가세요. 바루스가 궁극기를 사용해 퇴로를 차단하기 전에 정글러와 함께 빠르게 압박하세요.', item: '갈라진 하늘을 첫 코어로 올려 전투 지속력을 높이세요. 신발은 바루스의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도로 바루스의 사거리 안으로 빠르게 파고드세요.' },
    '베인': { lv1: '베인은 (Q)\'구르기\'로 거리를 조절하며 (W)\'은화살\'의 고정 피해를 입히니 무리하게 진입하지 마세요. 첫 웨이브에서는 (Q)\'엔토포 타격\'으로 둔화를 걸며 최대한 피해를 줄이고 체력을 보존하는 데 집중하세요. 평타 교환보다는 스킬 쿨타임을 기다리며 경험치를 챙기는 것이 좋아요.', lv3: '베인의 (E)\'선고\'에 벽으로 밀려나 기절하지 않도록 벽에서 떨어져 위치를 잡으세요. (W)\'길을 여는 자\'의 피해 감소 효과로 (W)\'은화살\'의 피해를 버티며 돌진해 상대를 기절시키세요. (E)\'발놀림\'으로 보호막을 얻으며 빠르게 접근한 뒤 (Q)\'엔토포 타격\'을 두 번 맞춰 적을 기절시키고 끌어당기세요.', lv6: '(R)\'총공세\'로 베인을 벽 너머로 밀어내면 큰 피해를 입히며 순식간에 킬각을 잡을 수 있어요. 하지만 베인이 (R)\'결전의 시간\'을 켜면 (Q)\'구르기\'로 투명해지니, 상대의 투명 상태가 끝나는 타이밍에 맞춰 스킬을 쓰세요. 라인을 당겨 정글러의 도움을 받고 (E)\'발놀림\'의 보호막으로 베인의 집중 공격을 견디세요.', item: '판금 장화와 가시 갑옷을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고 가시 갑옷은 방어력을 높이며 기본 공격에 맞을 때 피해를 되돌려줘요.', spell: '점멸과 순간이동을 추천해요. 점멸은 (E)\'발놀림\'과 함께 (Q)\'구르기\'로 거리를 벌리는 베인을 따라잡을 때 쓰고, 순간이동으로 라인 손실을 줄이세요.' },
    '볼리베어': { lv1: '1~2레벨에는 볼리베어의 (Q)\'번개 강타\'로 인한 기절과 접근을 조심해야 해요. (Q)\'엔토포 타격\'으로 거리를 유지하며 미니언을 챙기고, 볼리베어가 (Q)\'번개 강타\'로 달려들면 (E)\'발놀림\'으로 거리를 벌리세요. 볼리베어의 초반 평타 교환이 강한 구간이니 무리하게 붙지 마세요.', lv3: '볼리베어가 (W)\'광란의 상처\'로 표식을 남기고 체력을 회복하는 것을 막는 게 중요해요. (Q)\'엔토포 타격\'을 두 번 적중시켜 발생하는 충격파로 볼리베어의 진입을 끊어주거나, (W)\'광란의 상처\' 표식이 남았을 때는 (E)\'발놀림\'으로 거리를 두어 회복을 못 하게 하세요. (E)\'천공 분열\'은 번개가 떨어지는 곳에 피해와 둔화를 주니 그 자리를 피하고, 볼리베어가 범위 안에서 보호막을 얻었다면 교환을 미루세요.', lv6: '볼리베어가 (R)\'폭풍을 부르는 자\'로 도약해 포탑을 일시적으로 비활성화하며 다이브를 시도할 수 있으니 주의하세요. (R)\'총공세\'의 피해량과 체력 회복량 증가로 (W)\'광란의 상처\' 회복력을 상쇄하며 교환하세요. 볼리베어의 궁극기가 빠진 뒤에는 라인을 밀어 넣으며 적극적으로 압박하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 볼리베어의 마법 피해를 견디고 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. 볼리베어의 (W)\'광란의 상처\' 체력 회복을 억제하기 위해서예요.' },
    '블라디미르': { lv1: '(Q)\'수혈\'은 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없으니 체력 관리에 유의하세요. (Q)\'엔토포 타격\'으로 미니언과 함께 적을 타격하며 거리를 조절하고 최대한의 피해를 입히세요. 상대가 강화된 스킬을 사용하려는 타이밍에는 뒤로 물러나며 피해를 최소화하세요.', lv3: '(E)\'선혈의 파도\'는 투사체가 적 유닛에 막히므로 미니언 뒤에 서서 피해를 줄이세요. 블라디미르가 (W)\'피의 웅덩이\'로 변해 대상 지정 불가 상태가 되면 스킬을 아꼈다가 웅덩이가 끝나는 순간 (W)\'길을 여는 자\'로 기절시키세요. (E)\'발놀림\'으로 빠르게 접근해 (Q)\'엔토포 타격\' 중첩을 쌓아 적을 끌어당기며 압박하세요.', lv6: '(R)\'혈사병\'에 감염되면 받는 피해가 늘어나니 감염된 동안에는 무리한 교전을 피하고 잠시 빠지세요. 상대의 (W)\'피의 웅덩이\'가 빠진 타이밍에 (R)\'총공세\'를 사용해 벽 너머로 밀어내며 강력하게 공격하세요. 라인을 당겨서 정글러와 함께 상대의 회복 수단을 끊어내며 처치각을 보세요.', item: '케이닉 루컨과 헤르메스의 발걸음을 추천해요. 케이닉 루컨은 높은 마법 저항력을 제공하고 헤르메스의 발걸음은 강인함으로 (E)\'선혈의 파도\' 둔화 지속시간을 줄여줘요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'수혈\'과 (R)\'혈사병\'의 체력 회복 효과를 감소시켜야 킬각을 잡을 수 있어요.' },
    '뽀삐': { lv1: '뽀삐는 (Q)\'망치 강타\'로 둔화 지대를 만들며 견제하니 폭발하기 전에 거리를 조절하세요. (P)\'강철의 외교관\' 방패를 다시 주우면 뽀삐가 보호막을 얻으니 방패가 떨어진 쪽으로 움직이기 전에 (Q)\'엔토포 타격\'으로 짧게 교환하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 켜면 돌진하는 적을 막고 이동 스킬을 못 쓰게 하니 주의하세요. (E)\'발놀림\'을 쓰기 전에 (W)\'굳건한 태세\'가 빠졌는지 확인하고, (W)\'길을 여는 자\'는 저지 불가 돌진이라 (W)\'굳건한 태세\'에 막히지 않아요. 뽀삐의 (E)\'용감한 돌진\'에 벽에 부딪혀 기절하지 않도록 벽 근처에서는 거리를 유지하세요.', lv6: '뽀삐가 (R)\'수호자의 심판\'을 사용하면 적을 멀리 날려버리니 집중하는 동안 범위에서 벗어나세요. (R)\'총공세\'를 활용해 뽀삐의 체력이 낮을 때 벽을 뚫고 들어가서 빠르게 몰아붙이세요. 뽀삐의 (R)\'수호자의 심판\'이 빠진 뒤에 적극적으로 싸우며 라인을 압박하세요.', item: '삼위일체와 판금 장화를 추천해요. 삼위일체는 전투 지속력을 높여주고 판금 장화는 뽀삐의 물리 피해를 줄여줘요.', spell: '점멸과 점화. 점화로 뽀삐의 체력을 깎고 (R)\'총공세\'를 사용해 킬각을 잡으세요.' },
    '사이온': { lv1: '사이온은 (E)\'학살자의 포효\'로 방어력을 낮추고 둔화를 걸며 견제하니 미니언 뒤에 숨지 말고 비껴서세요. (Q)\'대량 학살 강타\' 충전 동작이 보이면 옆으로 움직여 공중에 띄워지는 것을 피하세요. 짧은 틈에 (Q)\'엔토포 타격\'을 맞춰 둔화를 걸고 거리 조절을 하며 체력을 관리하세요.', lv3: '(W)\'영혼의 용광로\' 보호막이 켜진 상태에서 재시전하면 큰 피해를 입히니 보호막이 터지기 전에 (E)\'발놀림\'으로 거리를 벌리세요. (Q)\'대량 학살 강타\'의 기절을 피한 뒤 (W)\'길을 여는 자\'로 돌진해 상대의 흐름을 끊고 기절시키세요. (Q)\'엔토포 타격\'을 두 번 적중시켜 상대를 끌어당기며 딜교환을 이어가세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진해 띄워 올리니 일직선상에서 벗어나 옆으로 피하세요. 사이온이 돌진을 멈춘 순간 (R)\'총공세\'를 사용해 벽 너머로 밀어내고 단독 구도를 만들어 빠르게 체력을 깎으세요. (P)\'영광스러운 죽음\'으로 되살아나 공격할 때는 무리하게 붙지 말고 (E)\'발놀림\'으로 거리를 유지하세요.', item: '얼어붙은 건틀릿을 첫 코어로 가서 방어력을 챙기고 둔화 효과로 사이온의 추격을 늦추세요. 신발은 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 순간이동을 추천해요. 사이온은 라인 푸시력이 좋아 순간이동으로 빠르게 복귀하는 것이 중요해요.' },
    '사일러스': { lv1: '사일러스가 (Q)\'사슬 후려치기\'로 둔화를 걸고 (P)\'페트리사이트 폭발\'을 활용한 평타를 치러 올 때 (Q)\'엔토포 타격\'으로 거리를 조절하세요. 1~2레벨에는 사일러스의 사슬이 교차하는 지점을 피하면서 (Q)\'엔토포 타격\' 중첩을 쌓으며 안정적으로 파밍하세요. 사일러스의 초반 교전이 강하니 무리하게 맞붙기보다 거리를 유지하는 것이 좋아요.', lv3: '사일러스가 (W)\'국왕시해자\'로 돌진하며 체력을 회복하려고 할 때 (W)\'길을 여는 자\'를 사용하여 맞받아치세요. (E)\'도주 / 억압\'의 사슬에 맞으면 공중으로 떠오르니 사일러스의 사슬이 날아갈 때 옆으로 비켜서야 해요. (Q)\'엔토포 타격\'을 적중시켜 사일러스의 진입을 방해하며 딜교환을 시도하세요.', lv6: '사일러스가 (R)\'강탈\'로 (R)\'총공세\'를 가져가면 매우 위협적이니 체력 관리에 유의해야 해요. 사일러스가 (W)\'국왕시해자\'를 사용해 체력을 회복하는 타이밍에 (R)\'총공세\'를 켜고 강하게 몰아붙이세요. (R)\'총공세\' 상태에서는 방어력이 감소하므로 사일러스의 스킬을 정면으로 다 맞지 않도록 주의하세요.', item: '마법 저항력을 제공하는 헤르메스의 발걸음을 먼저 올려주세요. 첫 코어 아이템으로는 사일러스의 마법 피해를 견디며 생명선을 얻을 수 있는 맬모셔스의 아귀를 추천해요.', spell: '점멸과 점화를 추천해요. 사일러스가 (W)\'국왕시해자\'로 체력을 회복하는 것을 점화로 억제하세요.' },
    '세주아니': { lv1: '(Q)\'엔토포 타격\'을 사용하여 미니언과 함께 적을 견제하며 중첩을 쌓아요. 세주아니가 (Q)\'혹한의 맹습\'으로 진입하기 쉬운 구간이므로 거리를 유지하며 신중하게 행동하세요.', lv3: '세주아니가 (Q)\'혹한의 맹습\'을 먼저 사용하도록 유도한 뒤에 (E)\'발놀림\'으로 접근해요. 상대의 (W)\'혹한의 서릿발\'이 빠진 타이밍에 (W)\'길을 여는 자\'를 사용하여 안정적으로 딜교환을 해요.', lv6: '(R)\'총공세\'로 변신한 뒤에는 방어력이 낮아지므로 세주아니의 (R)\'빙하 감옥\'에 맞지 않도록 조심해요. 정글러의 개입을 대비해 라인 관리와 함께 주변 시야를 확보하며 플레이하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가요. 세주아니의 마법 피해와 군중 제어에 대비하면서 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화. 점멸로 거리를 조절하고 점화로 적에게 추가 피해를 입혀 킬을 노려요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 켜고 다가와 강력한 평타를 날리니 정면 승부는 피하세요. (Q)\'엔토포 타격\'으로 둔화를 걸며 체력을 깎고, 세트가 (P)\'투기장의 투지\'로 회복하기 전에 짧게 딜교환하고 빠지세요. 첫 웨이브부터 무리하게 붙지 말고 거리 조절에 집중하세요.', lv3: '세트의 (W)\'강펀치\'는 투지가 많을 때 고정 피해와 보호막이 강력하니, 투지가 가득 찼을 때는 (W)\'길을 여는 자\'의 피해 감소로 버티며 시간을 끄세요. (E)\'안면 강타\'는 양옆의 적을 끌어당겨 양쪽에 적이 있으면 기절시키니 세트를 사이에 두고 미니언과 반대편에 서지 말고, 스킬이 빠진 뒤 (E)\'발놀림\'으로 진입해 빠르게 딜교환하세요. 세트의 주력 스킬이 빠진 타이밍에 (Q)\'엔토포 타격\' 중첩을 쌓아 기절시키는 것이 중요해요.', lv6: '세트가 (R)\'대미 장식\'으로 제압하기 전에 (R)\'총공세\'를 사용하여 적을 멀리 밀어내거나 벽 너머로 날려버리세요. (R)\'총공세\' 상태에서는 방어력이 낮아지니 세트의 (Q)\'주먹다짐\' 평타 연계에 노출되지 않도록 빠르게 거리 조절을 하세요. 라인을 적당히 유지하며 정글러가 오면 세트의 (W)\'강펀치\'가 빠진 타이밍에 함께 몰아붙이세요.', item: '판금 장화와 얼어붙은 건틀릿을 추천해요. 판금 장화로 세트의 기본 공격 피해를 줄이고, 얼어붙은 건틀릿의 방어력과 둔화 효과로 세트의 접근을 억제하세요.', spell: '점멸과 점화를 추천해요. 세트의 (P)\'투기장의 투지\'를 통한 체력 회복을 점화의 치유 감소로 억제하며 킬각을 잡으세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 체력 비례 피해를 주고 (P)\'기 보호막\'으로 피해를 흡수해요. (P)\'기 보호막\'이 켜져 있을 때는 평타 교환을 피하고, 보호막이 사라진 뒤에 (Q)\'엔토포 타격\'으로 둔화를 걸며 견제하세요. 쉔이 기의 검을 소환하는 타이밍에 맞춰 거리를 조절하며 피해를 최소화하세요.', lv3: '(W)\'의지의 결계\'가 활성화되면 평타가 막히니 (Q)\'엔토포 타격\' 위주로 딜교환을 하세요. 쉔이 (E)\'그림자 돌진\'으로 들어올 때 저지 불가 상태인 (W)\'길을 여는 자\'를 충전해 사용하면 도발을 무시하고 역으로 기절시킬 수 있어요. 쉔의 도발이 빠진 뒤에 (E)\'발놀림\'으로 진입해 딜교환을 이어가세요.', lv6: '(R)\'단결된 의지\'로 쉔이 합류하면 그 사이 라인을 빠르게 밀어 포탑을 압박하세요. 쉔을 벽 쪽으로 몰아 (R)\'총공세\'를 사용해 벽을 뚫고 날려 보내며 큰 피해를 입히세요. (R)\'총공세\' 상태에서는 방어력이 낮아지니 쉔의 (Q)\'황혼 강습\' 강화 평타를 조심하세요.', item: '끝없는 절망을 첫 코어로 선택해 체력을 높이고 전투 중 체력을 회복하며 버티세요. 신발은 (E)\'그림자 돌진\'의 도발 지속 시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 쉔이 (R)\'단결된 의지\'로 다른 라인에 영향을 줄 때 빠르게 복귀하거나 합류하기 위해서예요.' },
    '쉬바나': { lv1: '(E)\'용암 분출\'의 사거리가 길기 때문에 무리하게 다가가지 말고 미니언을 활용하며 파밍을 하세요. (Q)\'엔토포 타격\'을 사용하여 적에게 둔화를 걸며 거리 조절을 하는 것이 좋아요.', lv3: '(Q)\'엔토포 타격\' 중첩을 쌓아 기절시키고 끌어당기는 충격파를 적중시키는 것이 중요해요. 쉬바나가 (W)\'지옥불 방패\'를 사용해 보호막을 얻고 다가올 때 (W)\'길을 여는 자\'로 맞대응하세요.', lv6: '쉬바나가 (R)\'용의 강림\'을 써서 변신하면 무리한 전투보다는 라인을 당겨서 관리하세요. (R)\'총공세\'를 사용하면 방어력이 낮아지므로 쉬바나의 강화된 (Q)\'잉걸불 일격\'을 조심하며 싸워야 해요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 가요. 쉬바나의 마법 피해에 대응하기 위해 마법 저항력을 확보하기 위해서예요.', spell: '점멸과 점화. 순간적인 진입과 킬을 노리기 위해서예요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 멀리서 마법 피해를 입히며 견제해요. (Q)\'엔토포 타격\'을 사용하여 스웨인의 체력을 깎으며 거리를 좁히세요. 스웨인이 (P)\'굶주린 새떼\'로 체력을 회복하기 전에 초반에 이득을 보는 것이 중요해요.', lv3: '스웨인이 (E)\'속박명령\'을 사용하면 파동이 돌아오는 방향을 보고 피해야 해요. (W)\'길을 여는 자\'로 기절시켜 흐름을 끊거나 (E)\'발놀림\'으로 빠르게 파고드세요. 스웨인의 (W)\'제국의 눈\' 둔화에 걸리면 움직임이 제한되니 주의하세요.', lv6: '스웨인이 (R)\'악의 승천\'을 사용하여 체력을 흡수하기 시작하면 무리하게 계속 싸우지 마세요. (R)\'총공세\'는 방어구 관통력이 늘어나는 대신 방어력이 낮아지니 스웨인의 피해에 주의하며 짧게 승부를 보세요. 스웨인의 둔화 효과에 걸리면 (E)\'발놀림\'을 사용하여 적절한 위치를 잡으세요.', item: '헤르메스의 발걸음과 가고일 돌갑옷을 가세요. 헤르메스의 발걸음은 강인함을 제공하고 가고일 돌갑옷은 마법 저항력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화는 스웨인이 (R)\'악의 승천\'을 통해 체력을 회복하는 양을 줄여줘요.' },
    '스카너': { lv1: '(Q)\'엔토포 타격\'을 활용해 미니언과 함께 적을 견제하며 적절한 거리를 유지하세요. 스카너의 (Q)\'부서진 대지/지반 돌출\' 강화 평타에 맞지 않도록 주의하며 안정적으로 라인을 형성하세요.', lv3: '스카너가 (W)\'대지의 수호자\'를 사용해 보호막을 얻었을 때는 딜교환을 잠시 미루세요. 스카너가 (E)\'이쉬탈의 격돌\'로 돌진해 오면 (W)\'길을 여는 자\'를 충전해 저지 불가 상태로 받아낸 뒤 밀어내고, (Q)\'엔토포 타격\' 중첩을 쌓아 기절을 노리세요.', lv6: '스카너의 (R)\'꿰뚫기\'에 제압당하면 스킬을 쓸 수 없으니 항상 거리를 조절하며 대응하세요. (R)\'총공세\'로 스카너를 벽 너머로 밀어낸 뒤 강화된 스킬로 빠르게 몰아붙이세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 마법 저항력과 강인함으로 스카너의 둔화 지속시간을 줄이고 체력을 높여야 해요.', spell: '점멸과 점화를 추천해요. (R)\'총공세\'를 사용할 때 점멸로 거리를 좁히고 점화로 스카너의 체력을 깎으며 마무리하세요.' },
    '신지드': { lv1: '신지드는 (Q)\'맹독의 자취\'를 깔아 지속 피해를 주고 (P)\'독성 급류\'로 빠르게 이동하며 괴롭혀요. 무리하게 쫓아가지 말고 (Q)\'엔토포 타격\'으로 미니언을 챙기며 신지드의 접근을 견제하세요. 독구름 위에서 계속 싸우면 체력 관리가 어려우니 거리 조절을 잘해야 해요.', lv3: '(W)\'초강력 접착제\' 위에 있으면 (E)\'발놀림\' 같은 이동기를 사용할 수 없으니 접착제가 빠진 것을 확인하고 진입하세요. 신지드가 (E)\'던져넘기기\'를 쓰려고 다가오면 (W)\'길을 여는 자\'의 저지 불가 상태로 받아치며 적을 밀어내세요. (Q)\'엔토포 타격\'을 두 번 맞혀 기절시키면 짧은 순간 동안 딜교환 주도권을 잡을 수 있어요.', lv6: '(R)\'광기의 물약\'을 마신 신지드는 능력치가 크게 오르고 (Q)\'맹독의 자취\'에 상처를 남기니 정면 승부는 피하세요. (W)\'초강력 접착제\'가 없는 상황에서 (R)\'총공세\'로 신지드를 벽 너머로 밀어내어 피해를 입히고 킬각을 잡으세요. 신지드가 라인을 계속 밀어내면 타워 근처에서 (E)\'발놀림\'으로 빠르게 합류하며 정글의 도움을 받으세요.', item: '얼어붙은 건틀릿과 헤르메스의 발걸음을 추천해요. 둔화 효과로 신지드의 이동을 제한하고 마법 저항력과 강인함으로 군중 제어 지속 시간을 줄여야 해요.', spell: '점멸과 순간이동을 추천해요. 신지드의 강력한 라인 푸시력에 대응해 빠르게 복귀하고 운영을 통해 이득을 보셔야 해요.' },
    '신짜오': { lv1: '1~2레벨 구간에서는 신짜오의 (Q)\'삼조격\' 마지막 공격에 의한 공중 에어본을 조심하며 거리를 유지해요. (Q)\'엔토포 타격\'을 사용해 미니언과 함께 적을 둔화시키며 체력을 깎아 두세요.', lv3: '3레벨 이후 신짜오가 (E)\'무쌍돌격\'으로 진입할 때 (W)\'길을 여는 자\'를 사용하여 피해를 줄이고 기절을 노려요. 신짜오의 (Q)\'삼조격\'이 마지막 공격까지 이어지지 않도록 스킬을 활용해 적절히 대응하세요.', lv6: '신짜오가 (R)\'현월수호\'를 사용하여 범위 밖의 공격을 무시하며 버틸 때 (R)\'총공세\'로 변신해 맞대응해요. 상대의 궁극기 범위 밖으로 움직이거나 정글러를 호출하여 라인 관리와 함께 교전을 준비하세요.', item: '판금 장화와 얼어붙은 심장을 가요. 신짜오의 기본 공격 피해를 줄이고 방어력을 높이기 위해서예요.', spell: '점멸과 점화를 선택해요. 신짜오의 (P)\'결심\'을 통한 체력 회복을 억제하고 킬을 노리기 위해서예요.' },
    '아이번': { lv1: '(Q)\'덩굴뿌리\'에 속박되지 않게 거리 조절을 하며 미니언 뒤에서 버텨주세요. (Q)\'엔토포 타격\'으로 둔화를 걸며 기회를 보되 초반 견제는 최대한 받아내야 해요.', lv3: '(E)\'발놀림\'으로 빠르게 접근한 뒤 (W)\'길을 여는 자\'를 충전해 상대를 기절시키고 딜교환을 해요. 아이번이 (E)\'보호의 씨앗\'으로 보호막을 씌워 거리 조절을 하려 하니 계속해서 압박하세요.', lv6: '(R)\'총공세\'를 사용하여 아이번을 벽 너머로 밀어내고 빠르게 체력을 깎아 킬각을 잡으세요. (R)\'데이지!\'가 소환되면 충격파에 공중으로 띄워지지 않도록 주의하며 라인을 밀어 정글의 도움을 유도해요.', item: '헤르메스의 발걸음, 끝없는 절망. 마법 저항력과 강인함으로 속박 시간을 줄이고 전투 중 체력을 회복하며 버티기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 점멸로 (Q)\'덩굴뿌리\' 이후 변수를 만들고 순간이동으로 빠르게 라인에 복귀하기 위해 선택해요.' },
    '아지르': { lv1: '(Q)\'사막의 맹습\'을 통한 견제를 조심하며 미니언을 챙기는 데 집중하세요. (Q)\'엔토포 타격\'을 사용하여 최대한 적의 거리를 좁히며 파밍을 시도해요. 아지르의 병사 공격 범위에 너무 오래 머물지 않도록 조절하세요.', lv3: '(W)\'일어나라!\'를 통한 지속적인 견제를 조심하며 (Q)\'엔토포 타격\'으로 중첩을 쌓으세요. 아지르가 (E)\'신기루\'로 거리를 벌릴 때 (W)\'길을 여는 자\'를 사용하여 진입해요. (E)\'발놀림\'으로 보호막을 얻으며 아지르의 공격 타이밍을 흐트러뜨리세요.', lv6: '(R)\'총공세\'를 사용하여 아지르를 벽 너머로 밀어내며 강력하게 몰아붙이세요. 아지르가 (R)\'황제의 진영\'으로 밀어내며 거리를 벌릴 수 있으니 주의가 필요해요. 정글러와 함께 움직이며 아지르의 퇴로를 차단하며 싸우세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가요. 아지르의 마법 피해를 줄이고 체력을 높이기 위해서예요.', spell: '점멸과 점화. (R)\'총공세\' 상태에서 아지르를 확실하게 처치하기 위해 선택해요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 둔화를 걸며 견제할 때 거리를 조절하세요. (P)\'암살자의 표식\' 원 경계에서 강화 평타를 맞지 않도록 주의하며 (Q)\'엔토포 타격\'으로 둔화를 거는 것이 좋아요. 아칼리의 기력이 빠진 타이밍을 노려 짧게 딜교환을 시도하세요.', lv3: '아칼리가 (E)\'표창곡예\'로 표식을 남기고 돌진하면 (W)\'길을 여는 자\'로 기절을 시켜 대응하세요. (W)\'황혼의 장막\' 안의 아칼리는 대상으로 지정할 수 없지만 (Q)\'엔토포 타격\'은 대상 지정 스킬이 아니라 연막 안으로 그대로 쓸 수 있어요. (E)\'발놀림\'으로 보호막을 얻으며 아칼리의 진입 타이밍을 흘려주는 것이 중요해요.', lv6: '아칼리가 (R)\'무결처형\'으로 진입하며 체력이 낮아지면 (R)\'총공세\'를 사용해 맞대응하세요. (W)\'황혼의 장막\'을 쓰면 억지로 쫓지 말고 라인을 관리하며 정글의 지원을 기다려요. 아칼리가 (R)\'무결처형\'을 다시 사용하여 돌진하는 경로를 미리 파악하고 대응하세요.', item: '헤르메스의 발걸음을 먼저 올려 아칼리의 마법 피해를 줄이세요. 첫 코어 아이템으로는 체력과 공격력을 모두 챙길 수 있는 갈라진 하늘을 추천해요.', spell: '점멸과 탈진을 추천해요. 탈진은 아칼리가 (R)\'무결처형\'으로 들어올 때 피해량을 감소시켜 생존을 도와줘요.' },
    '아크샨': { lv1: '아크샨의 (Q)\'복수의 부메랑\'은 적에게 맞을수록 사거리가 늘어나니 미니언 뒤에 숨기보다 부메랑 궤적에서 벗어나며 거리를 유지하세요. (Q)\'엔토포 타격\'을 적중시켜 둔화를 걸고 체력 관리에 집중하며 경험치를 챙기세요. 초반에는 상대의 사거리가 훨씬 길기 때문에 신중하게 움직여야 해요.', lv3: '(E)\'발놀림\'으로 빠르게 접근한 뒤 (W)\'길을 여는 자\'를 사용하여 아크샨을 기절시켜 흐름을 끊으세요. 아크샨이 (E)\'영웅의 비상\'으로 도망가기 전에 빠르게 스킬을 연계해 피해를 입히는 것이 중요해요. (W)\'길을 여는 자\'의 피해 감소 효과를 활용해 상대의 기본 공격 피해를 최대한 받아내세요.', lv6: '(R)\'총공세\'를 사용하여 아크샨을 벽 쪽으로 밀어내고 강력한 피해를 입히며 킬각을 잡으세요. 하지만 방어력이 낮아진 상태에서 (R)\'인과응보\'의 큰 피해를 입을 수 있으니 체력 관리에 유의하세요. 정글러와 함께 (E)\'영웅의 비상\' 경로를 예측해 아크샨을 압박하며 라인을 관리하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 아크샨의 기본 공격 피해를 줄여주고 갈라진 하늘은 체력과 공격력을 동시에 챙기며 전투 지속력을 높여줘요.', spell: '점멸과 순간이동을 선택하세요. 점멸은 (R)\'총공세\'와의 연계나 갑작스러운 진입에 필요하고 순간이동은 탑 라인의 복귀와 합류를 위해 필수적이에요.' },
    '아트록스': { lv1: '아트록스가 (Q)\'다르킨의 검\'의 끝부분을 맞히면 공중에 띄워지니 범위를 잘 피하며 미니언을 챙기세요. (Q)\'엔토포 타격\'으로 적을 둔화시키며 거리를 조절하고, 상대가 스킬을 쓴 뒤에 짧게 교환하세요.', lv3: '아트록스가 (W)\'지옥사슬\'을 사용하면 빠르게 중앙에서 벗어나야 하며, (Q)\'다르킨의 검\'의 사거리를 조심하세요. 아트록스의 돌진기인 (E)\'파멸의 돌진\'이 빠진 것을 확인한 뒤 (W)\'길을 여는 자\'로 맞대응하며 (Q)\'엔토포 타격\' 중첩을 쌓으세요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 사용하면 체력 회복량이 크게 늘어나니 정면 싸움은 피하고 (W)\'길을 여는 자\'의 피해 감소로 버티며 지속시간이 끝나기를 기다리세요. (R)\'세계의 종결자\'가 끝난 뒤 상대의 체력이 낮다면 (R)\'총공세\'로 벽 너머로 밀어내며 몰아붙여 킬을 노려보세요.', item: '판금 장화와 가시 갑옷을 구매하세요. 판금 장화는 물리 피해를 줄여주고 가시 갑옷은 (P)\'사신 태세\'와 (E)\'파멸의 돌진\'의 회복을 억제해요.', spell: '점멸과 점화. 점화로 아트록스의 (P)\'사신 태세\'와 (E)\'파멸의 돌진\' 회복을 줄이면 교환에서 앞설 수 있어요.' },
    '암베사': { lv1: '1~2레벨 구간에는 암베사가 (P)\'용사냥개의 발걸음\'으로 스킬 사용 후 돌진하며 압박하니 거리 조절에 신경 써야 해요. (Q)\'엔토포 타격\'으로 적을 둔화시켜 접근을 늦추고 웨이브를 안정적으로 받아내세요. (Q)\'교활한 휩쓸기\'의 날 부분에 맞지 않도록 주의하세요.', lv3: '암베사가 (W)\'배척\'으로 보호막을 생성하며 피해를 입히려 할 때는 공격을 멈추고 기다리세요. (E)\'찢어 가르기\'로 둔화를 걸며 들어올 때 (W)\'길을 여는 자\'를 사용해 암베사의 진입을 차단하고 기절시키세요. (E)\'발놀림\'으로 보호막을 얻으며 상대의 연계 피해를 견뎌내는 것이 중요해요.', lv6: '암베사의 (R)\'공개 처형\'은 가장 멀리 있는 대상을 제압하니 거리 조절에 주의하며 위치를 잡으세요. 제압에 걸리면 아무것도 할 수 없으니 조심하고, 암베사의 궁극기가 빠지면 (R)\'총공세\'를 켜고 적극적으로 싸우세요. (R)\'총공세\' 상태에서는 (W)\'길을 여는 자\'의 재사용 대기시간이 초기화되니 이를 활용해 몰아붙이세요.', item: '코어로 갈라진 하늘을 가서 체력과 공격력을 확보하세요. 신발은 암베사의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 암베사의 체력이 낮을 때 점화로 마무리하며 회복 효과를 억제하세요.' },
    '애니비아': { lv1: '애니비아가 (Q)\'냉기 폭발\'로 멀리서 견제하며 냉각을 걸 수 있으니 거리를 잘 조절하세요. (Q)\'엔토포 타격\'을 사용하여 미니언과 함께 적을 견제하며 파밍에 집중하세요. 구체가 폭발할 때 기절하지 않도록 주의하며 옆으로 움직여야 해요.', lv3: '애니비아가 (Q)\'냉기 폭발\'을 쓴 직후에는 (E)\'동상\'의 피해가 매우 커지니 무리하게 들어가지 마세요. (Q)\'냉기 폭발\'이 빗나갔을 때 (W)\'길을 여는 자\'로 돌진하여 (Q)\'엔토포 타격\'의 둔화와 기절을 노리며 딜교환을 하세요. 애니비아가 (W)\'결정화\'로 경로를 막으면 잠시 물러나서 기다리세요.', lv6: '애니비아가 (R)\'얼음 폭풍\'을 사용하여 장판을 깔면 둔화에 걸리기 쉬우니 주의하세요. (R)\'총공세\'를 사용하여 벽을 넘으며 빠르게 접근해 애니비아를 압박하세요. 애니비아는 치명적인 피해를 입으면 (P)\'환생\'으로 체력을 회복하니, 알이 되었을 때 빠르게 처리해야 해요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 애니비아의 마법 피해를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 유체화를 추천해요. 유체화로 (Q)\'냉기 폭발\'과 (R)\'얼음 폭풍\'의 둔화를 극복하며 거리를 좁힐 수 있어요.' },
    '야스오': { lv1: '야스오가 (Q)\'강철 폭풍\'을 사용해 일직선으로 견제하면 거리를 조절하며 미니언을 챙기세요. (Q)\'엔토포 타격\' 중첩을 쌓아 야스오의 (P)\'낭인의 길\' 보호막이 사라진 시점에 맞춰 충격파를 시도하세요. 초반에는 야스오의 이동을 통한 보호막 생성을 의식하며 짧게 끊어 치는 것이 좋아요.', lv3: '야스오의 (W)\'바람 장막\'은 투사체만 막으니 (W)\'길을 여는 자\'와 (E)\'발놀림\' 같은 돌진 스킬은 막히지 않아요. (Q)\'강철 폭풍\' 중첩이 쌓여 에어본이 발생하기 전에 (W)\'길을 여는 자\'로 야스오를 밀어내고 기절시키세요. (E)\'발놀림\'으로 거리를 좁히며 야스오의 (E)\'질풍검\' 돌진을 예측해 대응하는 것이 중요해요.', lv6: '야스오의 (Q)\'강철 폭풍\' 두 번 중첩에 의한 에어본을 맞으면 (R)\'최후의 숨결\'로 이어질 수 있으니 조심하세요. (R)\'총공세\' 상태에서는 방어력이 감소하므로 (E)\'발놀림\'의 보호막을 활용하며 적절한 타이밍을 잡으세요. 야스오가 (E)\'질풍검\'으로 거리를 벌리려 하면 (R)\'총공세\'로 뒤쫓아 강화된 스킬로 몰아붙이는 것이 좋아요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 체력과 공격력을 동시에 챙기세요. 신발은 야스오의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 야스오의 (P)\'낭인의 길\' 보호막을 깎은 뒤 점화로 마무리 피해를 더하면 좋아요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리가 늘어난 평타 견제를 하며 (P)\'바위 피부\'로 점점 단단해져요. 1~2레벨에는 오공의 (Q)\'파쇄격\'에 맞아서 방어력이 낮아지기 전에 (Q)\'엔토포 타격\'으로 먼저 견제하며 거리를 조절하세요. 교환이 길어지면 오공의 방어력이 높아지니 짧게 치고 빠지는 것이 좋아요.', lv3: '오공이 (W)\'분신 전사\'로 투명해지며 분신을 남기면 진짜 위치를 잘 파악해야 해요. 오공이 (E)\'근두운 급습\'으로 돌진해 들어올 때 (E)\'발놀림\'으로 보호막을 얻으며 대응하고, 오공이 분신을 사용한 직후에 (W)\'길을 여는 자\'를 써서 진입을 막으세요. (W)\'분신 전사\'의 분신에 (Q)\'엔토포 타격\'의 두 번째 효과를 낭비하지 않도록 주의하세요.', lv6: '오공이 (R)\'회전격\'을 사용해 공중에 띄우려 할 때 (W)\'길을 여는 자\'의 저지 불가 상태를 활용해 맞서세요. (R)\'총공세\' 상태가 되면 피해량과 회복량이 늘어나니 오공이 (R)\'회전격\'을 사용한 직후에 강하게 몰아붙여 킬각을 보세요. 오공의 (E)\'근두운 급습\'과 (R)\'회전격\' 연계가 위협적이니 정글러를 부르거나 라인을 당겨서 관리하세요.', item: '갈라진 하늘을 첫 코어로 가서 전투력을 높이세요. 신발은 오공의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 오공에게 추가 피해를 입히며 킬각을 잡으세요.' },
    '오로라': { lv1: '오로라는 (Q)\'이중 저주\'를 던진 뒤 다시 불러들여 경로상의 적에게 피해를 입히니 돌아오는 경로를 조심하세요. 오로라가 (Q)\'이중 저주\'로 견제할 때 (Q)\'엔토포 타격\'으로 거리를 좁히며 압박하세요.', lv3: '오로라가 (E)\'마법의 문\'을 사용하여 뒤로 도약하면 (E)\'발놀림\'으로 따라붙으세요. 오로라가 (W)\'장막 너머로\'를 사용해 투명해지면 무리하게 쫓지 마세요. (Q)\'엔토포 타격\'으로 충격파를 맞힌 뒤 (W)\'길을 여는 자\'로 딜교환을 시도하세요.', lv6: '오로라가 (R)\'세계의 경계\'를 사용하여 영역을 만들면 영역 안에서 움직임이 제한될 수 있으니 주의하세요. (R)\'세계의 경계\' 영역 밖으로 (R)\'총공세\'를 통해 밀어내며 킬각을 보세요. 오로라가 (W)\'장막 너머로\'로 도망가지 못하게 정글러와 협동하세요.', item: '마법 피해가 주력인 오로라를 상대로 헤르메스의 발걸음을 올려 마법 저항력을 확보하세요. 코어 아이템은 갈라진 하늘을 선택해 전투력을 높이세요.', spell: '점멸과 점화를 추천해요. 오로라는 (P)\'영혼 방호술\'로 체력을 회복하니 점화로 회복 효과를 감소시키세요.' },
    '오른': { lv1: '오른은 (P)\'간이 대장간\' 덕분에 초반부터 기본 방어력과 마법 저항력이 높아요. (Q)\'용암 균열\'이 생성하는 용암 기둥의 위치를 확인하고 옆으로 피하면서 (Q)\'엔토포 타격\'으로 짧게 견제하세요. 무리하게 붙지 말고 거리 조절을 하며 경험치와 체력을 관리해요.', lv3: '(E)\'화염 돌진\'이 지형지물에 부딪히면 띄우니 벽 근처에 서지 마세요. 오른이 (W)\'불꽃 풀무질\'로 전진할 때 (W)\'길을 여는 자\'를 사용해 저지 불가 상태로 버티며 상대의 진입을 끊으세요. (E)\'발놀림\'의 보호막을 활용해 피해를 흡수하고 (Q)\'엔토포 타격\'을 두 번 적중시켜 기절시키세요.', lv6: '(R)\'대장장이 신의 부름\'의 정령이 다가올 때 정령의 경로에서 벗어나고, 오른이 재시전해 돌진하는 방향을 피하세요. (R)\'총공세\'로 오른을 벽 쪽으로 밀어내어 추가 피해를 입히고, 총공세 상태의 강화된 (Q)\'엔토포 타격\'으로 빠르게 공격하세요. 오른의 체력이 낮아져도 (P)\'간이 대장간\' 때문에 킬각이 까다로우니 정글러를 불러 함께 공격해요.', item: '얼어붙은 건틀릿을 첫 코어로 가서 체력과 방어력을 챙기고 스킬 후 기본 공격으로 오른을 둔화시키세요. 신발은 강인함과 마법 저항력을 제공하는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 오른은 체력이 매우 많아 순식간에 잡기 어려우므로 순간이동으로 라인 복귀와 운영에 집중하세요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 방어력과 이동 속도를 낮추면 정면 대결을 피하며 거리를 유지하세요. (Q)\'엔토포 타격\'을 사용해 견제하며 올라프가 도끼를 주우러 올 때를 대비해야 해요. 체력이 낮아진 올라프는 (P)\'광전사의 분노\'로 인해 흡혈이 강해지니 주의하세요.', lv3: '올라프가 (W)\'버티기\'를 사용하여 보호막을 얻는 동안에는 무리하게 딜교환을 하지 마세요. (W)\'길을 여는 자\'를 활용해 상대의 접근을 막거나 거리를 조절하며 (Q)\'엔토포 타격\' 중첩을 쌓으세요. 올라프의 (Q)\'역류\' 도끼를 피하면서 (Q)\'엔토포 타격\'의 충격파로 반격하세요.', lv6: '올라프가 (R)\'라그나로크\'를 쓰면 이동 방해 효과에 면역이 되므로 (W)\'길을 여는 자\'의 기절을 노리기보다 거리를 벌리세요. (R)\'총공세\'를 켜서 전투를 이어가되 정글러의 지원을 받아 빠르게 상황을 정리하는 것이 좋아요. 올라프의 궁극기가 끝난 뒤 (Q)\'엔토포 타격\'을 사용하여 다시 압박하세요.', item: '판금 장화와 가시 갑옷을 선택하세요. 올라프의 기본 공격 피해를 줄이고 방어력을 높여야 해요.', spell: '점멸과 점화를 추천해요. 점화로 올라프의 (P)\'광전사의 분노\' 생명력 흡수 회복을 줄이세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'으로 견제하고 (P)\'사냥꾼의 길\' 덕분에 두 번째 공격마다 마법 피해를 입혀요. (Q)\'엔토포 타격\'을 사용하여 거리 조절을 하며 요네의 평타 사거리 밖에서 움직이세요.', lv3: '요네가 (E)\'영혼해방\'으로 들어왔다 돌아가는 구간을 노려 (W)\'길을 여는 자\'를 충전하며 공격을 받아내세요. (Q)\'필멸의 검\' 중첩이 쌓이면 돌풍으로 띄워 올리니 중첩이 쌓이기 전에 거리를 조절하세요. (W)\'영혼 가르기\'로 요네가 보호막을 얻었을 때는 무리하게 (Q)\'엔토포 타격\'으로 딜교환을 하지 마세요.', lv6: '요네가 (R)\'운명봉인\'으로 끌어당기며 공중으로 띄우면 스킬을 쓸 수 없으니 궁극기 사거리 안에서는 거리 조절에 유의하세요. (R)\'총공세\'를 사용하면 방어력이 감소하니 요네의 폭발적인 피해를 주의하며 싸워야 해요.', item: '첫 코어로 갈라진 하늘을 가서 전투 지속력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 요네의 체력을 낮춰서 킬각을 잡는 데 도움을 받으세요.' },
    '요릭': { lv1: '요릭은 (Q)\'최후의 의식\'으로 기본 공격 시 추가 피해를 입히고 체력을 회복하며 무덤을 만들어요. (Q)\'엔토포 타격\'으로 요릭의 이동 속도를 늦추며 짧게 딜교환하고 무덤이 쌓이지 않게 견제하세요. (P)\'영혼의 길잡이\'로 소환된 망령들이 주변을 공격하니 너무 깊게 들어가지 않도록 주의하세요.', lv3: '(E)\'애도의 안개\' 표식이 남으면 망령들이 빠르게 달려드니 구체를 피하는 것이 최우선이에요. (W)\'망자의 진\' 벽은 공격을 받으면 파괴되니 가로막혔을 때는 벽을 부수거나 돌아가세요. 요릭의 (Q)\'최후의 의식\' 강화 공격이 빠진 타이밍에 진입해 빠르게 공격하고 나오세요.', lv6: '(R)\'군도의 장송곡\'으로 안개 마녀가 소환되면 지속적인 피해가 커지니 마녀와 요릭이 함께 있는 상황을 피하세요. (R)\'총공세\'를 사용해 요릭을 벽 너머로 밀어내어 마녀의 지원을 받지 못하는 일대일 구도를 만드세요. 요릭이 마녀와 망령으로 라인을 빠르게 밀 때는 (Q)\'엔토포 타격\'으로 적절히 받아치며 정글러를 부르세요.', item: '판금 장화로 요릭과 망령들의 기본 공격 피해를 줄이세요. 얼어붙은 건틀릿의 방어력과 스킬 사용 후 기본 공격 시 적용되는 둔화 효과로 적의 추격을 늦추세요.', spell: '점멸과 점화를 추천해요. 요릭의 (Q)\'최후의 의식\'으로 인한 체력 회복을 점화로 억제해야 딜교환에서 앞설 수 있어요.' },
    '우디르': { lv1: '우디르는 (Q)\'야생 발톱\'의 추가 피해와 공격 속도로 초반 평타 교환이 강해요. (E)\'불길 쇄도\' 태세로 다가와 기절을 걸려 하니 적절한 거리를 유지하며 (Q)\'엔토포 타격\'으로 둔화를 거세요. 무리하게 붙지 말고 경험치 위주로 라인을 받으세요.', lv3: '우디르가 (E)\'불길 쇄도\'로 기절을 시도할 때 (W)\'길을 여는 자\'를 충전해 피해를 줄이고 적을 밀어내세요. (W)\'강철 갑옷\'의 보호막과 회복이 켜진 동안은 딜교환을 피하고 보호막이 사라진 뒤 (Q)\'엔토포 타격\'으로 기절시키세요. (E)\'발놀림\'으로 보호막을 얻으며 상대의 진입 경로를 차단하세요.', lv6: '(R)\'날개 돋친 폭풍\'의 둔화 때문에 접근이 어려우니 (E)\'발놀림\'으로 빠르게 진입해 (R)\'총공세\'로 벽 너머로 밀어내세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 면역 상태가 되면 (W)\'길을 여는 자\'의 기절이 통하지 않으니 주의하세요. 라인을 당겨 정글 개입을 유도하고 (E)\'불길 쇄도\' 면역이 끝난 뒤에 (Q)\'엔토포 타격\' 충격파로 기절을 노리세요.', item: '판금 장화와 태양불꽃 방패를 추천해요. (Q)\'야생 발톱\'의 강력한 기본 공격 피해를 판금 장화로 줄이고 태양불꽃 방패의 체력과 방어력으로 버티며 근접전을 수행하세요.', spell: '점멸과 점화를 추천해요. (W)\'강철 갑옷\'의 체력 회복을 점화로 억제하고 부족한 마무리 피해를 보충하세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'을 던져 둔화를 걸고 (P)\'화염의 메아리\' 불꽃으로 견제하니 거리를 조절하며 파밍하세요. (Q)\'엔토포 타격\'으로 적절히 대응하되, 우르곳의 평타 사거리가 더 길어 무작정 붙으면 피해가 커요. 폭약이 떨어지는 위치를 보고 빠르게 움직이며 피해를 최소화하세요.', lv3: '우르곳이 (E)\'경멸\'로 돌진해 뒤로 던지려 할 때 (W)\'길을 여는 자\'로 피해를 줄이며 받아치세요. (W)\'심판의 원\'은 다른 스킬을 맞힌 적을 우선 공격하니 (Q)\'부식성 폭약\'을 맞았다면 빠르게 (E)\'발놀림\'으로 거리를 벌리세요. 우르곳의 돌진기가 빠진 시점에 진입해 딜교환을 시도하세요.', lv6: '(R)\'불사의 공포\' 섬광탄이 꽂히면 체력이 낮을 때 처형당할 수 있으니 즉시 거리를 벌리세요. (R)\'총공세\'를 사용하여 우르곳을 벽 쪽으로 밀어내면 큰 피해를 입히며 일방적인 구도를 만들 수 있어요. 정글러가 올 때는 (Q)\'엔토포 타격\' 충격파로 우르곳을 기절시키고 끌어당겨 함께 점사하세요.', item: '판금 장화를 신어 우르곳의 기본 공격 피해를 줄이세요. 얼어붙은 건틀릿을 첫 코어로 올려 방어력을 높이고 스킬 사용 후 기본 공격으로 상대를 둔화시키세요.', spell: '점멸과 순간이동을 추천해요. 순간이동을 통해 라인 복귀와 운영에 힘을 싣고 점멸로 (R)\'총공세\' 연계를 노리세요.' },
    '워윅': { lv1: '1~2레벨에는 워윅이 (Q)\'야수의 송곳니\'로 도약해 최대 체력 비례 피해를 주고 회복하니 짧은 딜교환만 하세요. (Q)\'야수의 송곳니\'는 대상 지정 스킬이라 미니언 뒤에 숨어도 막히지 않으니 무리하게 붙지 마세요. (Q)\'엔토포 타격\'을 활용해 둔화를 걸며 거리를 유지하고 상대가 (P)\'끝없는 허기\'로 회복하기 전에 빠르게 빠지세요.', lv3: '워윅이 (E)\'원시의 포효\'를 켜면 피해량이 감소하고 이후 공포를 거니, 포효가 끝날 때까지 (W)\'길을 여는 자\'로 피해를 줄이며 버티세요. (W)\'피의 사냥\'으로 인해 워윅의 공격 속도가 빨라진 상태에서는 정면 승부를 피하고 (E)\'발놀림\'으로 빠르게 거리를 벌리세요. (Q)\'엔토포 타격\'을 두 번 맞춰 기절시킨 뒤 (W)\'길을 여는 자\'로 밀어내면 상대의 추격을 끊을 수 있어요.', lv6: '(R)\'무한의 구속\'은 제압 효과라 맞으면 스킬이나 점멸을 전혀 쓸 수 없으니 정글러가 근처에 있을 때 라인을 너무 밀지 마세요. (R)\'총공세\'를 사용해 워윅을 벽 쪽으로 밀어내면 추가 피해를 입히며 체력을 빠르게 깎을 수 있어요. 제압은 수은 장식띠로만 풀 수 있으니 상대 궁극기가 있을 때는 항상 도주 경로를 확보하세요.', item: '판금 장화와 가시 갑옷을 추천해요. 판금 장화로 기본 공격 피해를 줄이고, 가시 갑옷의 치유 감소 효과로 (P)\'끝없는 허기\'와 (Q)\'야수의 송곳니\'의 회복량을 억제하세요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과가 있어야 워윅의 강력한 회복력을 억제하며 킬각을 잡을 수 있어요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타고 빠르게 접근하며 체력을 회복해요. (Q)\'엔토포 타격\'으로 적중시켜 둔화를 걸어 거리 조절을 하고, 상대의 (P)\'아이오니아의 열정\' 중첩이 쌓이기 전에 짧게 교환하세요. 미니언 체력이 낮은 구간에 서 있지 않도록 위치를 잡으세요.', lv3: '(E)\'쌍검협무\'의 두 칼날이 모이는 지점을 (E)\'발놀림\'으로 빠르게 피해서 기절을 방지하세요. 이렐리아가 (W)\'저항의 춤\'을 충전할 때 (W)\'길을 여는 자\'의 피해 감소 효과로 버티며 진입해 기절을 시키세요. (Q)\'엔토포 타격\'을 두 번 맞춰 기절시키면 (Q)\'칼날 쇄도\'의 회복 흐름을 끊을 수 있어요.', lv6: '이렐리아가 (R)\'선봉진격검\'을 맞히면 불안정 상태가 되어 (Q)\'칼날 쇄도\'가 초기화되고 결계를 통과할 때 피해와 둔화를 입으니 (E)\'발놀림\' 보호막으로 버티며 무리하게 결계를 넘지 마세요. (R)\'총공세\'로 이렐리아를 벽 너머로 밀어내어 미니언으로부터 격리시키면 상대의 추격 능력을 낮출 수 있어요. (W)\'길을 여는 자\'로 상대를 기절시키고 (Q)\'엔토포 타격\'으로 이어가며 압박하세요.', item: '판금 장화와 얼어붙은 건틀릿을 추천해요. 판금 장화는 이렐리아의 기본 공격 피해를 줄여주고, 얼어붙은 건틀릿은 방어력과 체력을 제공하며 주문 검 효과로 적을 둔화시켜요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\'를 통한 이렐리아의 체력 회복을 억제하고 킬각을 잡으세요.' },
    '일라오이': { lv1: '1~2레벨에는 (P)\'고대신의 예언자\' 촉수가 있는 벽 근처에서 싸우지 말고 라인 중앙을 유지하세요. 일라오이가 (Q)\'촉수 강타\'로 견제할 때 (Q)\'엔토포 타격\'으로 응수하며 짧은 딜교환 뒤에 빠르게 빠지세요. 상대가 무리하게 다가오면 둔화를 활용해 거리를 조절하세요.', lv3: '(E)\'영혼의 시험\'에 맞아 영혼이 분리되면 영혼과 너무 멀어지지 않게 주의하며 촉수가 없는 곳으로 이동하세요. (W)\'혹독한 가르침\'으로 도약하는 타이밍에 (W)\'길을 여는 자\'를 사용해 피해를 줄이고 일라오이를 밀어내어 촉수 범위를 벗어나세요. (E)\'발놀림\'으로 빠르게 위치를 잡고 (Q)\'엔토포 타격\'으로 표식을 남기며 짧게 치고 빠지세요.', lv6: '(R)\'믿음의 도약\'을 사용하면 주변에 수많은 촉수가 생성되니 즉시 (R)\'총공세\'로 일라오이를 붙잡아 벽 너머나 촉수가 없는 곳으로 밀어내세요. 총공세 상태에서 강화된 (Q)\'엔토포 타격\'과 (E)\'발놀림\'을 사용해 빠르게 피해를 입히고 빠져나오세요. 라인을 당겨 받아 일라오이가 벽을 끼고 싸우는 구도를 피하고 정글러의 개입을 유도하세요.', item: '판금 장화와 끝없는 절망을 추천해요. 판금 장화는 물리 피해와 기본 공격 피해를 줄여주며, 끝없는 절망은 체력과 방어력을 높이고 전투 중 체력을 회복해 끈질기게 버티게 해줘요.', spell: '점멸과 순간이동을 추천해요. 점멸은 생존과 공격에 필수이며, 순간이동으로 라인 복귀를 빠르게 하여 손해를 줄이세요.' },
    '자크': { lv1: '자크가 (Q)\'탄성 주먹\'으로 긴 사거리에서 견제할 수 있으니 거리를 유지하세요. (Q)\'엔토포 타격\'을 활용해 짧은 거리에서 딜교환을 하며 미니언 사이의 위치를 신경 쓰세요. 자크가 (W)\'불안정 물질\'로 폭발하기 전에 거리를 벌려 피해를 최소화하세요.', lv3: '자크가 (E)\'새총 발사\'로 날아올 때는 (E)\'발놀림\'을 사용해 보호막을 얻으며 대응하세요. 자크의 (W)\'불안정 물질\' 폭발 범위 안에 들어가지 않도록 주의하며 딜교환을 하세요. (Q)\'엔토포 타격\'을 적중시켜 자크를 둔화시킨 뒤 짧게 교환하고 빠지는 것이 좋아요.', lv6: '자크가 (R)\'바운스!\'로 공중에 띄우려 할 때 주의하며 거리를 조절하세요. (R)\'총공세\' 상태로 들어가 킬을 노릴 때는 자크가 (P)\'세포 분열\'로 부활할 수 있음을 기억하세요. (W)\'길을 여는 자\'를 사용하여 자크의 진입을 차단하거나 원하는 방향으로 밀어내세요.', item: '마법 피해가 강력한 자크를 상대하기 위해 헤르메스의 발걸음을 먼저 구매하세요. 첫 코어 아이템으로는 체력과 공격력을 모두 챙길 수 있는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 자크의 회복을 억제하며 싸우세요.' },
    '자헨': { lv1: '자헨은 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하니 초반에 붙는 것을 조심하세요. (Q)\'엔토포 타격\'을 사용하여 거리를 유지하며 적을 둔화시키고 체력을 깎으세요. 자헨이 (Q)\'다르킨의 글레이브\'를 쓰며 다가올 때는 (E)\'발놀림\'으로 거리를 벌리는 것이 좋아요.', lv3: '(W)\'공포의 귀환\'은 일직선으로 내지르는 스킬이니 방향을 보고 옆으로 비켜서세요. 자헨의 (E)\'찬란한 쇄도\'가 들어올 때 (Q)\'엔토포 타격\'의 중첩을 활용해 기절을 노려보세요. 자헨이 (Q)\'다르킨의 글레이브\' 재사용으로 적을 띄우기 전에 (E)\'발놀림\'으로 위치를 잡는 것이 중요해요.', lv6: '자헨이 (R)\'단호한 판결\'로 날아올라 내려찍으며 체력을 회복할 수 있으니 낙하 지점을 주의하세요. 자헨은 (P)\'전쟁 단련\' 결심이 가득 차면 부활할 수 있으니 체력이 낮아 보여도 마무리까지 방심하지 마세요. 자헨이 (E)\'찬란한 쇄도\'로 도망치려 하면 (R)\'총공세\' 상태의 강화된 스킬로 추격하세요.', item: '자헨의 기본 공격 피해를 줄이기 위해 판금 장화를 먼저 선택하세요. 첫 코어 아이템은 체력과 공격력을 동시에 챙길 수 있는 갈라진 하늘을 추천해요.', spell: '점멸과 점화를 추천해요. 자헨은 (Q)\'다르킨의 글레이브\'와 (R)\'단호한 판결\'로 체력을 회복하니 점화로 회복 효과를 줄이세요.' },
    '잭스': { lv1: '잭스가 (Q)\'도약 공격\'으로 순식간에 거리를 좁히거나 (P)\'가차없는 맹공\'을 쌓으며 강하게 압박하니 거리를 잘 유지하세요. (Q)\'엔토포 타격\'을 사용하여 잭스의 이동 속도를 늦추며 미니언을 챙기고 짧게 딜교환한 뒤 빠르게 빠져나오세요.', lv3: '잭스가 (E)\'반격\'을 사용하면 기본 공격을 모두 피하므로 (E)\'발놀림\'을 사용하여 위치를 옮기며 스킬이 끝나기를 기다리세요. 잭스가 (E)\'반격\' 이후 기절을 시키기 전에 (W)\'길을 여는 자\'를 사용해 피해를 줄이며 버티는 것이 중요해요. 잭스의 (Q)\'도약 공격\'이 빠진 타이밍에 (Q)\'엔토포 타격\'을 맞춰 딜교환을 시도하세요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용해 방어력과 마법 저항력이 높아지면 정면 대결을 피하고 적절히 거리를 벌리세요. (R)\'총공세\'를 사용하여 잭스를 벽 너머로 밀쳐내거나 변수를 만들며 싸움을 조절하세요. 잭스의 (Q)\'도약 공격\'이 들어오는 경로를 예측해 (W)\'길을 여는 자\'로 대응하면 킬각을 잡기 좋아요.', item: '판금 장화를 먼저 구매하여 잭스의 기본 공격 피해를 줄이세요. 첫 코어 아이템으로는 전투 지속력을 높여주는 갈라진 하늘을 선택해요.', spell: '점멸과 점화를 추천해요. 점화로 잭스의 체력을 깎고 킬을 마무리하기에 적합해요.' },
    '제이스': { lv1: '제이스가 캐논 형태로 (Q)\'전격 폭발\'을 쏘며 멀리서 견제할 때 (Q)\'엔토포 타격\'의 두 중첩 충격파를 맞히기 위해 거리를 잘 조절하세요. 제이스가 해머 형태로 바꿔 (Q)\'하늘로!\'로 접근하며 둔화를 걸 때 (E)\'발놀림\'을 활용하여 빠르게 반응하며 대응해요.', lv3: '제이스의 해머 (E)\'천둥 강타\'에 밀려나지 않도록 (W)\'길을 여는 자\'의 저지 불가 상태를 적절한 타이밍에 활용하여 맞서세요. 제이스가 (E)\'가속 관문\'을 통해 (Q)\'전격 폭발\'을 더 강력하게 쏠 때 (Q)\'엔토포 타격\'을 맞춰 접근을 방해하며 딜교환을 하세요.', lv6: '제이스가 (R)\'머큐리 캐논\'을 사용하여 방어력을 깎을 때는 (W)\'길을 여는 자\'를 아껴두며 피해를 줄이세요. (R)\'총공세\'를 사용해 제이스를 벽 너머로 밀어낸 뒤 변형된 스킬로 빠르게 몰아붙여 킬을 노리세요. 제이스가 (E)\'천둥 강타\'로 거리를 벌리려 하면 (E)\'발놀림\'을 사용하여 끝까지 추격하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 제이스의 기본 공격 피해를 줄이고 전투 지속력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. (R)\'총공세\' 도중 제이스의 체력이 낮을 때 점화를 사용하여 확실하게 마무리하세요.' },
    '초가스': { lv1: '초가스는 (E)\'날카로운 가시\'로 평타마다 전방에 피해와 둔화를 주니 정면에 서 있지 마세요. 지면에 원이 생기는 (Q)\'파열\'을 조심하며 (Q)\'엔토포 타격\'으로 미니언과 함께 견제하며 거리를 유지해요. 초가스가 (P)\'육식\'으로 미니언을 처치하며 체력을 회복할 수 있으니 막타 타이밍을 잘 확인하세요.', lv3: '초가스가 (W)\'흉포한 울부짖음\'을 쓰면 침묵에 걸려 스킬을 못 쓰게 되니 원뿔 범위 밖으로 피하세요. 침묵이 빠진 후에 (W)\'길을 여는 자\'로 돌진하여 (Q)\'엔토포 타격\'의 충격파를 노려보세요. 초가스의 (Q)\'파열\'을 맞지 않도록 이동기인 (E)\'발놀림\'을 아껴두며 거리 조절을 해요.', lv6: '초가스의 (R)\'포식\'은 큰 고정 피해를 입히고 대상을 처치하면 초가스가 성장하니 체력 관리에 신경 써야 해요. (R)\'총공세\'는 최대 체력이 줄어 (R)\'포식\'에 더 위험해지니 초가스의 체력이 충분히 깎였을 때만 켜고, 강화된 (W)\'길을 여는 자\'의 피해 감소로 버티며 마무리하세요. 초가스가 (Q)\'파열\'로 공중으로 띄우면 (R)\'총공세\' 도중에 대응하기 어려우니 주의해요.', item: '초가스의 마법 피해를 견디기 위해 헤르메스의 발걸음을 먼저 올려요. 첫 코어 아이템은 체력을 높여주는 태양불꽃 방패를 사용해요.', spell: '점멸과 점화를 추천해요. 점화로 초가스의 (P)\'육식\' 회복 효과를 줄이며 승부를 보세요.' },
    '카밀': { lv1: '카밀은 (Q)\'정확성 프로토콜\'로 강화 평타를 넣고 (P)\'적응형 방어 체계\'로 보호막을 얻으니 평타 교환을 조심하세요. (Q)\'엔토포 타격\'을 계속 맞춰 둔화를 걸고 거리 조절을 하며 카밀의 보호막이 사라진 뒤에 딜교환을 하세요.', lv3: '(W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 느려지고 카밀이 체력을 회복하니 안쪽으로 파고드세요. (E)\'갈고리 발사\'로 진입하는 순간 (W)\'길을 여는 자\'를 사용해 피해를 줄이고 기절시켜 진입을 끊으세요. (E)\'발놀림\'으로 빠르게 거리를 좁히며 (Q)\'엔토포 타격\' 충격파로 기절을 노리세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 탈출할 수 없으니 벽 근처에서 싸울 때 주의하고 카밀의 진입 경로를 확인하세요. 카밀의 궁극기가 빠진 뒤 (R)\'총공세\'를 사용하여 적을 벽 너머로 밀어내고 빠르게 체력을 깎으세요. 정글러가 올 때는 (E)\'발놀림\'으로 아군에게 빠르게 합류하며 보호막을 공유하세요.', item: '갈라진 하늘과 판금 장화를 추천해요. 판금 장화로 카밀의 평타 피해를 줄이고 갈라진 하늘의 체력과 피해 효과로 유지력을 높이세요.', spell: '점멸과 점화를 추천해요. 카밀이 (W)\'전술적 휩쓸기\'로 회복하는 양을 점화의 치유 감소로 줄여야 해요.' },
    '카사딘': { lv1: '1~2레벨에는 (Q)\'무의 구체\'가 대상에게 날아가는 스킬이라 미니언 뒤에 숨어도 맞으니 체력을 아끼며 거리를 조절하세요. (Q)\'엔토포 타격\'을 적중시켜 둔화를 걸고 짧은 딜교환을 시도하며 체력 관리를 하는 것이 중요해요.', lv3: '(E)\'발놀림\'으로 빠르게 접근한 뒤 (W)\'길을 여는 자\'로 기절시켜 카사딘의 진입 흐름을 끊으세요. (Q)\'무의 구체\'의 보호막은 마법 피해만 흡수하니 물리 피해 위주인 크산테는 보호막을 신경 쓰지 말고 교환을 이어가세요. 상대의 (E)\'힘의 파동\' 둔화가 빠진 타이밍에 진입해야 효율적으로 딜교환을 할 수 있어요.', lv6: '(R)\'총공세\'를 사용하여 상대를 벽 쪽으로 밀어내며 큰 피해를 입히고 킬각을 잡으세요. 상대가 (R)\'균열 이동\'으로 빠르게 도망칠 수 있으니 스킬을 신중하게 사용하고 정글러를 불러 함께 압박하세요.', item: '헤르메스의 발걸음과 케이닉 루컨을 추천해요. 마법 저항력을 높이고 마법 피해를 흡수하는 보호막을 얻어 견제를 견디기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 기동력을 보완하고 라인 복귀를 빠르게 하여 운영의 이점을 가져가기 위해서예요.' },
    '카시오페아': { lv1: '(Q)\'맹독 폭발\'의 견제를 받으며 체력을 관리하는 것이 중요해요. (Q)\'엔토포 타격\'을 사용하여 거리를 좁히며 미니언을 함께 챙기려고 노력하세요. 상대의 사거리가 길기 때문에 무리한 진입보다는 경험치를 챙기며 버티는 것이 좋아요.', lv3: '상대의 (W)\'독기의 늪\'이 깔리면 (E)\'발놀림\'이나 (W)\'길을 여는 자\' 같은 이동 스킬을 사용할 수 없으니 주의하세요. (W)\'독기의 늪\'이 빠진 것을 확인한 뒤에 (Q)\'엔토포 타격\'으로 상대를 둔화시키고 진입하세요. (E)\'쌍독니\'의 피해를 최소화하면서 짧게 딜교환을 시도하세요.', lv6: '(R)\'총공세\'를 사용하여 진입할 때 상대의 (R)\'석화의 응시\'를 정면으로 바라보지 않도록 방향을 조절하세요. (W)\'길을 여는 자\'의 피해 감소 효과를 활용하며 카시오페아의 집중 공격을 견뎌내야 해요. 라인을 적절히 관리하며 정글러를 불러서 압박하는 것이 좋아요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높여서 상대의 마법 피해를 줄이고 강인함으로 군중 제어 효과를 짧게 만들기 위해서예요.', spell: '점멸과 정화. (R)\'석화의 응시\'에 걸렸을 때 기절 상태를 즉시 해제하고 대응하기 위해서예요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'으로 (P)\'폭풍의 표식\'을 쌓으며 멀리서 견제해요. (Q)\'엔토포 타격\'을 두 번 맞춰 기절과 끌어당기기를 준비하며 거리를 조절하세요. (Q)\'천둥의 표창\'은 처음 맞은 적에게 적중하니 미니언 사이에서 움직이며 표식이 쌓이지 않게 하세요.', lv3: '케넨이 (E)\'번개 질주\'로 빠르게 다가오면 (W)\'길을 여는 자\'를 사용해 기절시키세요. 케넨이 (W)\'전류 방출\'을 사용해 표식을 터뜨리기 전에 (E)\'발놀림\'으로 들어가 보호막을 얻으며 딜교환을 시도해요. 케넨의 스킬이 빠진 타이밍을 포착하는 것이 중요해요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용해 폭풍을 소환하면 근처에서 멀어지며 마법 피해를 피하세요. 케넨의 궁극기가 끝난 직후 (R)\'총공세\'를 사용해 벽 너머로 밀어내며 킬각을 노려보세요. 케넨이 (E)\'번개 질주\'로 도망가지 못하도록 정글러와 함께 압박하는 것이 좋아요.', item: '맬모셔스의 아귀를 첫 코어로 가서 케넨의 마법 피해를 견뎌내세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\'으로 인한 기절은 정화로 풀 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'이 오르기 전까지는 사거리가 짧으니 압박을 시도하세요. (Q)\'엔토포 타격\'을 사용하여 케일의 체력을 깎으며 중첩을 쌓고, 중첩을 모아 끌어당겨 압박하세요. 케일이 (Q)\'광휘의 일격\'으로 견제하려 할 때 거리를 조절하며 웨이브를 가져오세요.', lv3: '케일이 (E)\'화염주문검\'을 사용하여 잃은 체력 비례 피해를 입히려 할 때 (W)\'길을 여는 자\'로 피해를 감소시키며 진입하세요. (Q)\'엔토포 타격\'의 둔화 효과를 이용해 케일의 이동을 제한하고 (E)\'발놀림\'으로 빠르게 거리를 좁히세요. 케일이 (Q)\'광휘의 일격\'을 먼저 사용하도록 유도한 뒤 싸움을 거세요.', lv6: '케일이 (R)\'신성한 심판\'을 사용하여 자신을 무적으로 만들면 딜 교환을 멈추고 잠시 기다리세요. 무적 효과가 끝난 직후 (R)\'총공세\'를 활성화하여 (Q)\'엔토포 타격\'과 (E)\'발놀림\'의 강화된 성능으로 몰아붙여야 해요. 케일이 궁극기를 아군에게 사용했다면 그 타이밍에 맞춰 (W)\'길을 여는 자\'로 강하게 압박하세요.', item: '갈라진 하늘을 코어 아이템으로 가서 전투 지속력을 높이세요. 신발은 케일의 마법 피해를 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 케일이 강해지기 전에 점화로 킬을 가져와 격차를 벌리세요.' },
    '코그모': { lv1: '코그모의 (Q)\'부식성 침\' 견제를 조심하며 (Q)\'엔토포 타격\'으로 미니언을 정리해 체력을 관리하세요. 상대의 공격 사거리가 매우 길기 때문에 무리하게 다가가기보다 적절한 거리에서 경험치를 챙기세요. 초반에는 최대한 피해를 줄이며 성장에 집중하는 것이 중요해요.', lv3: '(E)\'발놀림\'으로 빠르게 접근한 뒤 (W)\'길을 여는 자\'로 기절시켜 딜교환을 시도하세요. 코그모가 (E)\'공허의 분비물\'을 사용해 둔화를 걸면 진입이 어려우니 이를 먼저 피하는 것이 좋아요. (Q)\'엔토포 타격\'을 두 번 맞춰 충격파를 발사해 상대를 기절시키면 더 확실하게 공격할 수 있어요.', lv6: '(R)\'총공세\'를 사용해 코그모를 벽으로 밀쳐내며 강력하게 압박하세요. 다만 (R)\'총공세\' 상태에서는 방어력과 마법 저항력이 감소하여 (W)\'생체마법 폭격\'의 마법 피해에 더 취약해지므로 진입 타이밍을 신중하게 결정해야 해요. 정글러와 함께 (E)\'발놀림\'으로 빠르게 진입하여 킬각을 잡으세요.', item: '헤르메스의 발걸음과 대자연의 힘을 추천해요. 코그모의 강력한 마법 피해를 줄이고 강인함으로 둔화 지속시간을 줄이기 위해서예요.', spell: '점멸과 순간이동을 사용하세요. 부족한 접근력을 보완하고 라인 복귀를 빠르게 하기 위해서예요.' },
    '코르키': { lv1: '1레벨 웨이브 때 (Q)\'인광탄\' 견제를 최소화하며 (Q)\'엔토포 타격\'으로 빠르게 미니언을 처리하세요. 무리하게 진입하기보다 경험치를 챙기며 거리를 유지하는 것이 좋아요.', lv3: '(E)\'발놀림\'으로 빠르게 접근한 뒤 (W)\'길을 여는 자\'를 충전해 코르키를 기절시키세요. 상대가 (W)\'발키리\'로 도망가거나 (E)\'개틀링 건\'으로 저항할 때 타이밍을 맞춰 스킬을 사용하세요.', lv6: '(R)\'총공세\'를 사용하여 코르키를 벽으로 밀어 넣어 큰 피해를 입히고 킬각을 잡으세요. 상대가 (R)\'미사일 폭격\'으로 거리 조절을 하려 하니 주의하며 정글러와 함께 압박하세요.', item: '헤르메스의 발걸음과 얼어붙은 건틀릿을 추천해요. 마법 저항력으로 견제를 버티고 둔화 효과로 코르키를 추격하기 좋아요.', spell: '점멸과 순간이동을 추천해요. 원거리 챔피언을 추격하거나 라인 복귀를 빠르게 하기 위해 필요해요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식이 남은 대상에게 첫 평타를 강하게 넣으며 (Q)\'실명 공격\'으로 시야를 좁히며 견제해요. (Q)\'엔토포 타격\'으로 퀸의 접근을 둔화로 막으며 거리 조절을 하고 미니언을 챙기세요. 퀸이 (E)\'공중제비\'로 거리를 벌리려 하면 무리하게 따라가지 마세요.', lv3: '퀸이 (E)\'공중제비\'를 사용하여 뒤로 물러나며 둔화를 걸면 (E)\'발놀림\'을 사용하여 빠르게 따라붙으세요. (Q)\'엔토포 타격\' 중첩을 쌓아 충격파를 발사하면 퀸을 기절시키고 (W)\'길을 여는 자\'로 이어서 딜교환을 시도해요. 퀸이 (Q)\'실명 공격\'을 먼저 사용하도록 유도하는 것이 좋아요.', lv6: '퀸이 (R)\'후방 지원\'을 사용해 이동 속도가 빨라지면 접근과 이탈이 쉬워지니 라인 관리에 신경 써야 해요. (R)\'총공세\'를 사용해 퀸을 벽 너머로 밀어내면 강력한 피해를 줄 수 있지만 방어력이 감소하니 주의하세요. 퀸이 (E)\'공중제비\'로 도망갈 때 (E)\'발놀림\'과 연계해 확실하게 압박하세요.', item: '판금 장화로 퀸의 기본 공격 피해를 줄여주세요. 첫 코어 아이템은 갈라진 하늘을 선택해 전투 지속력을 높이는 것이 좋아요.', spell: '점멸과 유체화를 추천해요. 유체화로 퀸의 (E)\'공중제비\' 이후 움직임을 따라잡고 거리를 좁히기 편해요.' },
    '클레드': { lv1: '클레드는 (Q)\'덫날리기\'로 끌어당기며 초반에 강하게 압박해요. (Q)\'엔토포 타격\'으로 둔화를 걸며 스칼의 체력을 깎고, 덫에 맞았을 때는 끌려가지 않게 클레드와 거리를 벌리세요. 첫 웨이브부터 무리하게 붙지 말고 짧은 딜교환만 반복하세요.', lv3: '클레드가 (E)\'이랴!\'로 진입하면 (W)\'길을 여는 자\'를 충전해 피해를 줄이고 상대의 흐름을 끊어내세요. (W)\'버럭버럭\'의 빠른 공격이 시작되면 (E)\'발놀림\'으로 빠르게 거리를 벌려 마지막 공격을 피하는 게 중요해요. (Q)\'엔토포 타격\'을 반복해서 적중시켜 기절시킨 뒤 짧게 딜교환하세요.', lv6: '(R)\'돌겨어어억!!!\'의 돌진 경로에서 벗어나 스칼의 충돌 피해와 밀려남을 피하세요. 클레드가 스칼에서 내려 챔피언 피해량이 줄어든 상태라면 (R)\'총공세\'로 벽에 밀어붙여 빠르게 처치하세요. 라인을 당겨 정글러를 부르고, 적이 진입할 때 (W)\'길을 여는 자\'로 쳐내며 협공하세요.', item: '판금 장화는 기본 공격 피해를 줄여줘서 (W)\'버럭버럭\'의 피해를 견디기 좋아요. 갈라진 하늘을 첫 코어로 선택해 체력을 보충하고 교전 중 체력을 회복하며 버티세요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드는 체력 회복 수단이 부족하므로 점화로 빠르게 마무리하기 좋아요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 피해를 입히고 (P)\'절대 미각\' 중첩을 쌓으려 해요. (Q)\'엔토포 타격\'으로 짧게 딜교환하며 중첩이 세 번 쌓여 기절하기 전에 뒤로 빠지세요. 혀는 처음 맞는 유닛에게 적중하므로 미니언 뒤에서 (Q)\'엔토포 타격\'을 사용해 안전하게 견제하세요.', lv3: '탐 켄치가 (W)\'심연 잠수\'로 착지하며 띄우는 범위를 보고 범위 밖으로 비켜서세요. (E)\'두꺼운 피부\' 보호막이 켜지기 전에 빠르게 딜교환을 마치거나, 보호막이 사라진 뒤에 (Q)\'엔토포 타격\'을 맞히세요. (E)\'발놀림\'으로 거리를 조절하며 (P)\'절대 미각\' 중첩이 쌓이지 않게 주의하세요.', lv6: '(R)\'총공세\'로 탐 켄치를 벽 너머로 밀어내며 강력한 피해를 입히고 빠르게 몰아붙이세요. 총공세 상태에서는 (W)\'길을 여는 자\'가 더 이상 적을 밀어내거나 기절시키지 않으니 주의하며 딜교환하세요. (P)\'절대 미각\' 중첩이 쌓인 상태에서 탐 켄치에게 붙으면 (R)\'집어삼키기\'에 먹힐 수 있으니 거리 조절을 잘하세요.', item: '칠흑의 양날 도끼를 가서 방어력을 깎고 체력을 보충해 탐 켄치의 높은 체력에 대응하세요. 신발은 마법 저항력과 강인함을 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'를 통한 체력 회복을 억제하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 훔치고 둔화를 걸며 초반 평타 교환이 강해요. (Q)\'엔토포 타격\'으로 둔화를 걸며 짧게 딜교환하고 빠르게 빠지세요. 트런들은 (P)\'헌납\'으로 유닛이 죽을 때마다 체력을 회복하니 미니언이 많이 죽는 타이밍에 무리하게 싸우지 마세요.', lv3: '(W)\'얼음 왕국\' 영역 안에 있으면 트런들의 공격 속도와 이동 속도가 오르니 영역 밖에서 싸우세요. (E)\'얼음 기둥\'에 막혀 접근이 어려울 때는 (E)\'발놀림\'으로 위치를 빠르게 잡으세요. 트런들의 (Q)\'깨물기\'가 들어올 때 (W)\'길을 여는 자\'로 피해를 줄이면서 기절시키면 짧은 딜교환에서 앞서요.', lv6: '트런들이 (R)\'진압\'으로 방어력을 훔쳐 가면 방어력이 급격히 낮아지니 즉시 거리를 벌리세요. (R)\'진압\' 효과가 끝난 뒤 (R)\'총공세\'로 트런들을 벽 너머로 밀어내고 강화된 스킬로 몰아붙이세요. (E)\'얼음 기둥\'으로 도망길을 막고 정글러를 부르는 갱킹이 잦으니 좁은 길목을 피하고 시야를 확보하세요.', item: '판금 장화와 가시 갑옷을 추천해요. 판금 장화는 트런들의 기본 공격 피해를 줄여주고 가시 갑옷은 방어력을 높이며 (P)\'헌납\'과 (W)\'얼음 왕국\'의 회복력을 깎아요.', spell: '점멸과 점화를 추천해요. 가시 갑옷과 함께 점화의 치유 감소를 사용하면 트런들의 강력한 회복 수단을 억제해 킬각을 잡기 편해요.' },
    '트린다미어': { lv1: '1~2레벨 구간에는 트린다미어의 (P)\'격노\'가 쌓이기 전에 (Q)\'엔토포 타격\'으로 거리를 조절하며 미니언을 받아먹으세요. 무리한 평타 교환은 트린다미어의 공격력을 높여주니 주의해야 해요.', lv3: '트린다미어가 (E)\'회전 베기\'를 사용해 들어오면 (W)\'길을 여는 자\'를 사용하여 적을 기절시키고 저항하세요. 트린다미어가 (W)\'조롱의 외침\'을 썼을 때 등을 돌리면 둔화에 걸리니 (E)\'발놀림\'으로 위치를 잡는 것이 중요해요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 켜면 죽지 않으므로 (R)\'총공세\'를 아껴두었다가 지속시간이 끝난 뒤에 사용하세요. (R)\'불사의 분노\'가 끝나는 순간 (Q)\'엔토포 타격\'으로 기절을 시키며 킬을 노리는 것이 좋아요.', item: '판금 장화와 얼어붙은 심장을 가세요. 판금 장화는 트린다미어의 기본 공격으로 받는 피해를 줄여주고 얼어붙은 심장은 방어력을 높여줘요.', spell: '점멸과 점화를 추천해요. 트린다미어가 (Q)\'피의 갈망\'으로 체력을 회복할 때 점화로 회복 효과를 억제하세요.' },
    '티모': { lv1: '티모는 (E)\'맹독 다트\'로 지속 피해를 주고 (Q)\'실명 다트\'로 실명을 걸어요. (Q)\'실명 다트\'에 맞은 동안은 평타 교환을 미루고 (Q)\'엔토포 타격\'으로 미니언을 정리하며 거리를 유지하세요. 수풀 근처에서는 (P)\'유격 전투\'로 숨어 기습하는 티모를 조심하며 천천히 다가가세요.', lv3: '(Q)\'실명 다트\'의 지속 시간 동안은 평타를 자제하고 (W)\'길을 여는 자\'의 피해 감소 효과로 티모의 견제를 받아내며 진입하세요. (E)\'발놀림\'으로 빠르게 접근한 뒤 (Q)\'엔토포 타격\'을 두 번 맞혀 티모를 기절시켜야 해요. (W)\'신속한 이동\'으로 도망가려는 티모를 기절시킨 뒤 딜교환을 마무리하세요.', lv6: '(R)\'유독성 함정\'을 밟으면 둔화와 피해를 입어 추격이 어려우니 버섯 위치를 잘 파악하며 움직이세요. (R)\'총공세\'로 티모를 벽 쪽으로 밀어내어 추가 피해를 입히고 빠르게 처치하는 것이 중요해요. (R)\'총공세\' 상태에서는 방어력이 낮아지므로 티모의 (E)\'맹독 다트\' 피해가 아프게 들어오니 주의하세요.', item: '갈라진 하늘을 첫 코어로 선택해 체력을 높이고 피해를 회복하세요. 신발은 헤르메스의 발걸음을 가서 (E)\'맹독 다트\'의 마법 피해를 줄이고 (R)\'유독성 함정\'의 둔화 시간을 단축하세요.', spell: '점멸과 순간이동을 추천해요. 원거리 챔피언인 티모를 상대로는 빠른 합류와 운영이 중요해요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'으로 원거리 견제를 하며 초반에 강하게 압박해요. (Q)\'엔토포 타격\'을 사용하여 상대의 접근을 늦추고 피해를 최소화하세요. (P)\'필멸자의 의지\'가 쌓여 강화된 공격이 들어오기 전에는 짧게 딜교환을 하고 물러나세요.', lv3: '(W)\'방호의 도약\'으로 진입하는 타이밍에 (W)\'길을 여는 자\'를 사용하여 받는 피해를 줄이고 적을 밀어내세요. (E)\'방패 돌격\'을 사용한 동안은 정면 공격이 통하지 않으니 무리하게 공격하지 말고 (E)\'발놀림\'으로 위치를 잡으세요. 상대의 핵심 스킬이 빠진 뒤에 (Q)\'엔토포 타격\' 중첩을 쌓아 기절을 노리세요.', lv6: '판테온이 (R)\'거대 유성\'으로 진입하면 (R)\'총공세\'를 사용하여 판테온을 벽 너머로 밀어내 흐름을 끊고 큰 피해를 주세요. (R)\'총공세\' 상태에서는 방어력이 감소하니 (E)\'방패 돌격\' 같은 생존기가 빠진 것을 확인하고 진입하세요. 판테온이 궁극기로 다른 라인에 개입하면 빠르게 라인을 밀어 넣어 손해를 강요하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 (W)\'방호의 도약\' 이후 이어지는 판테온의 기본 공격 피해를 줄여줘요. 갈라진 하늘은 체력을 높여 생존력을 더하고 공격 시 체력 회복으로 유지력을 높여줘요.', spell: '점멸과 순간이동을 추천해요. 판테온의 빠른 합류 능력에 대응하기 위해 순간이동으로 라인 복귀와 합류를 빠르게 하세요.' },
    '피들스틱': { lv1: '1~2레벨에는 피들스틱이 시야 밖에서 (Q)\'공포\'를 사용하여 접근을 막으려 할 것이니 조심하세요. 미니언과 함께 움직이며 거리를 조절하고 (Q)\'엔토포 타격\'을 활용해 견제하며 스택을 쌓으세요. 상대의 접근을 경계하며 차분히 파밍에 집중하며 대응해요.', lv3: '스킬이 모이면 (E)\'발놀림\'으로 진입하여 보호막을 얻으며 딜교환을 시도하세요. 피들스틱의 (E)\'수확\' 범위에 맞아 둔화에 걸리지 않도록 주의하며 (Q)\'엔토포 타격\'을 맞춰 대응하세요. 상대가 (W)\'풍작\'을 사용하여 체력을 회복하지 못하도록 끊어주는 것이 중요해요.', lv6: '6레벨 이후에는 피들스틱이 (R)\'까마귀 폭풍\'을 사용하여 갑작스럽게 진입할 수 있으니 조심하세요. (R)\'까마귀 폭풍\'에 맞으면 (W)\'길을 여는 자\'의 피해 감소로 버티며 범위 밖으로 나오고, 상대 궁극기가 빠진 뒤 (R)\'총공세\'로 몰아붙이세요. 라인 관리를 통해 정글러의 개입에 대비하는 태도가 필요해요.', item: '헤르메스의 발걸음과 심연의 가면을 가세요. 상대의 마법 피해를 견디고 마법 저항력을 높이기 위해서예요.', spell: '점멸과 정화를 추천해요. 피들스틱의 (Q)\'공포\'를 빠르게 해제하고 대응하기 위해서예요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 거리를 좁히며 급소를 노리려 하니 1~2레벨에는 무리한 교환을 피하세요. (Q)\'엔토포 타격\'을 맞춰 둔화를 걸고 거리를 조절하며 대응하세요. 급소가 드러난 방향으로 피오라가 파고들지 못하게 위치를 조절해 (P)\'치명적인 검무\' 회복을 막으세요.', lv3: '피오라의 (W)\'응수\'는 모든 공격과 이동 불가 효과를 막아내고 반격하니, (W)\'길을 여는 자\'를 쓰기 전에 피오라의 스킬이 빠졌는지 확인하세요. (W)\'응수\'가 켜진 동안 내 기절이 막히면 오히려 기절당할 수 있으니 주의해야 해요. (E)\'발놀림\'으로 거리를 조절하며 피오라의 (E)\'대가의 검술\' 둔화와 치명타를 피하세요.', lv6: '피오라가 (R)\'대결투\'를 사용하면 급소를 모두 가격해 큰 피해를 입히니 주의하세요. (R)\'총공세\'를 사용해 벽 너머로 피오라를 밀어내며 전투를 주도하세요. (R)\'총공세\' 상태에서는 방어력이 낮아지니 피오라의 연속적인 공격에 너무 오래 노출되지 않도록 해요.', item: '란두인의 예언을 첫 코어로 올려서 피오라의 치명타 피해를 줄이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화를 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 피오라의 (P)\'치명적인 검무\'와 (R)\'대결투\'를 통한 체력 회복을 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인 주도권을 가져가며 포탑 근처에서 이동 속도가 올라가요. 1~2레벨에는 포탑의 공격 사거리를 확인하며 미니언을 챙기고, 무리하게 진입하기보다 (Q)\'엔토포 타격\'으로 거리를 유지하며 견제하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 중앙에 맞으면 기절하니 수류탄이 떨어지는 위치를 잘 피하세요. (W)\'마법공학 초소형 로켓\'은 마우스 커서 방향으로 날아오니 하이머딩거의 정면에 서지 않도록 주의해요. 상대의 (E)\'CH-2 전자폭풍 수류탄\'이 빠졌을 때 (E)\'발놀림\'으로 빠르게 접근해 (Q)\'엔토포 타격\'의 충격파를 노려보세요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용한 직후에는 강화된 스킬의 위력이 매우 강력하니 조심해야 해요. (R)\'총공세\'를 사용해 진입할 때는 상대의 포탑을 먼저 제거하거나 포탑 사거리 밖에서 (W)\'길을 여는 자\'로 접근하는 것이 좋아요. 포탑이 없는 상황에서 하이머딩거의 빈틈을 노려 (R)\'총공세\'로 빠르게 몰아붙이세요.', item: '갈라진 하늘을 첫 코어로 올리고 신발은 헤르메스의 발걸음을 가세요. 마법 피해를 견디고 기절 지속시간을 줄이기 위해서예요.', spell: '점멸과 점화를 추천해요. 하이머딩거가 포탑을 깔고 거리를 벌릴 때 점멸로 접근하여 점화로 체력을 깎으며 마무리하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_ksante);
if (typeof module !== 'undefined') module.exports = top_ksante;
